INSERT INTO `banner_code_snapshot` (`id`, `code_content`, `created_at`) VALUES
(73, '<style>\r\n  @import url(\'https://fonts.googleapis.com/css2?family=Playfair+Display:wght@600;700&family=DM+Sans:wght@300;400;500&display=swap\');\r\n\r\n  :root {\r\n    --npx-c1: #0f0f0f;\r\n    --npx-c2: #1a1a2e;\r\n    --npx-c3: #16213e;\r\n    --npx-c4: #0f3460;\r\n    --npx-acc: #e94560;\r\n    --npx-acc2: #f5a623;\r\n    --npx-light: #f8f4ef;\r\n    --npx-muted: #a0a0b0;\r\n  }\r\n\r\n  .npx-popup-backdrop,\r\n  .npx-popup-backdrop * {\r\n    box-sizing: border-box;\r\n    margin: 0;\r\n    padding: 0;\r\n  }\r\n\r\n  .npx-popup-backdrop {\r\n    font-family: \'DM Sans\', sans-serif;\r\n    /* position: fixed; */\r\n    top: 0;\r\n    left: 0;\r\n    /* width: 100vw;\r\n    height: 100vh; */\r\n    background: rgba(0, 0, 0, 0.75);\r\n    backdrop-filter: blur(8px);\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    z-index: 9999;\r\n    /* padding: 20px; */\r\n  }\r\n\r\n  .npx-popup-overlay {\r\n    background: rgba(10, 10, 20, 0.92);\r\n    border-radius: 20px;\r\n    overflow: hidden;\r\n    display: flex;\r\n    flex-direction: column;\r\n    min-height: 580px;\r\n    width: 100%;\r\n    max-width: 900px;\r\n    border: 1px solid rgba(255, 255, 255, 0.08);\r\n    position: relative;\r\n    box-shadow: 0 30px 60px rgba(0, 0, 0, 0.5);\r\n    animation: npxPopIn 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;\r\n  }\r\n\r\n  @keyframes npxPopIn {\r\n    0% {\r\n      opacity: 0;\r\n      transform: scale(0.9) translateY(20px);\r\n    }\r\n\r\n    100% {\r\n      opacity: 1;\r\n      transform: scale(1) translateY(0);\r\n    }\r\n  }\r\n\r\n  .npx-skeleton {\r\n    display: flex;\r\n    flex-direction: column;\r\n    width: 100%;\r\n    gap: 12px;\r\n    animation: npxPulse 1.5s infinite ease-in-out;\r\n  }\r\n\r\n  .npx-skel-line {\r\n    background: rgba(255, 255, 255, 0.08);\r\n    border-radius: 6px;\r\n  }\r\n\r\n  @keyframes npxPulse {\r\n    0% {\r\n      opacity: 0.5;\r\n    }\r\n\r\n    50% {\r\n      opacity: 1;\r\n    }\r\n\r\n    100% {\r\n      opacity: 0.5;\r\n    }\r\n  }\r\n\r\n  .npx-popup-header {\r\n    background: linear-gradient(90deg, #0f3460, #16213e);\r\n    padding: 14px 22px;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: space-between;\r\n    border-bottom: 1px solid rgba(255, 255, 255, 0.07);\r\n  }\r\n\r\n  .npx-popup-header h2 {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: 17px;\r\n    color: #fff;\r\n    letter-spacing: 0.3px;\r\n  }\r\n\r\n  .npx-live-badge {\r\n    background: var(--npx-acc);\r\n    color: #fff;\r\n    font-size: 10px;\r\n    font-weight: 500;\r\n    padding: 3px 10px;\r\n    border-radius: 20px;\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 5px;\r\n    letter-spacing: 0.5px;\r\n  }\r\n\r\n  .npx-live-dot {\r\n    width: 6px;\r\n    height: 6px;\r\n    border-radius: 50%;\r\n    background: #fff;\r\n    animation: npxBlink 1.2s infinite;\r\n  }\r\n\r\n  @keyframes npxBlink {\r\n\r\n    0%,\r\n    100% {\r\n      opacity: 1;\r\n    }\r\n\r\n    50% {\r\n      opacity: 0.2;\r\n    }\r\n  }\r\n\r\n  .npx-popup-close {\r\n    width: 28px;\r\n    height: 28px;\r\n    border-radius: 50%;\r\n    border: 1px solid rgba(255, 255, 255, 0.15);\r\n    background: rgba(255, 255, 255, 0.06);\r\n    color: #ccc;\r\n    font-size: 16px;\r\n    cursor: pointer;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    line-height: 1;\r\n  }\r\n\r\n  .npx-popup-body {\r\n    display: grid;\r\n    grid-template-columns: minmax(0, 2fr) minmax(260px, 1fr);\r\n    flex: 1;\r\n    min-height: 0;\r\n  }\r\n\r\n  .npx-left-panel {\r\n    display: grid;\r\n    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);\r\n    border-right: 1px solid rgba(255, 255, 255, 0.07);\r\n    min-width: 0;\r\n  }\r\n\r\n  .npx-reel-section {\r\n    background: #0a0a14;\r\n    padding: 18px 16px;\r\n    border-right: 1px solid rgba(255, 255, 255, 0.06);\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 12px;\r\n  }\r\n\r\n  .npx-section-label {\r\n    font-size: 10px;\r\n    text-transform: uppercase;\r\n    letter-spacing: 1.5px;\r\n    color: var(--npx-muted);\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 6px;\r\n  }\r\n\r\n  .npx-section-label svg {\r\n    width: 12px;\r\n    height: 12px;\r\n    fill: var(--npx-acc);\r\n  }\r\n\r\n  .npx-reel-frame {\r\n    background: #111;\r\n    border-radius: 14px;\r\n    overflow: hidden;\r\n    position: relative;\r\n    aspect-ratio: 9/14;\r\n    border: 1px solid rgba(255, 255, 255, 0.08);\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    cursor: pointer;\r\n  }\r\n\r\n  .npx-reel-placeholder {\r\n    display: flex;\r\n    flex-direction: column;\r\n    align-items: center;\r\n    gap: 10px;\r\n    color: rgba(255, 255, 255, 0.3);\r\n  }\r\n\r\n  .npx-reel-placeholder svg {\r\n    width: 36px;\r\n    height: 36px;\r\n    opacity: 0.4;\r\n  }\r\n\r\n  .npx-reel-placeholder span {\r\n    font-size: 11px;\r\n    text-align: center;\r\n    max-width: 110px;\r\n    line-height: 1.5;\r\n  }\r\n\r\n  .npx-reel-frame .npx-play-btn {\r\n    width: 48px;\r\n    height: 48px;\r\n    border-radius: 50%;\r\n    background: rgba(233, 69, 96, 0.85);\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    position: absolute;\r\n    bottom: 14px;\r\n    right: 14px;\r\n    cursor: pointer;\r\n    transition: transform 0.15s;\r\n  }\r\n\r\n  .npx-reel-frame .npx-play-btn:hover {\r\n    transform: scale(1.1);\r\n  }\r\n\r\n  .npx-play-btn svg {\r\n    width: 18px;\r\n    height: 18px;\r\n    fill: #fff;\r\n    margin-left: 2px;\r\n  }\r\n\r\n  .npx-token-form {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 6px;\r\n  }\r\n\r\n  .npx-token-form label {\r\n    font-size: 10px;\r\n    color: var(--npx-muted);\r\n    letter-spacing: 0.5px;\r\n  }\r\n\r\n  .npx-token-form input {\r\n    background: rgba(255, 255, 255, 0.05);\r\n    border: 1px solid rgba(255, 255, 255, 0.1);\r\n    border-radius: 8px;\r\n    color: #fff;\r\n    font-size: 11px;\r\n    padding: 7px 10px;\r\n    font-family: monospace;\r\n    outline: none;\r\n    width: 100%;\r\n    transition: border-color 0.2s;\r\n  }\r\n\r\n  .npx-token-form input:focus {\r\n    border-color: var(--npx-acc);\r\n  }\r\n\r\n  .npx-token-form button {\r\n    background: var(--npx-acc);\r\n    color: #fff;\r\n    border: none;\r\n    border-radius: 8px;\r\n    padding: 7px;\r\n    font-size: 11px;\r\n    font-family: \'DM Sans\', sans-serif;\r\n    cursor: pointer;\r\n    font-weight: 500;\r\n    transition: opacity 0.2s;\r\n    margin-top: 2px;\r\n  }\r\n\r\n  .npx-token-form button:hover {\r\n    opacity: 0.85;\r\n  }\r\n\r\n  .npx-info-section {\r\n    background: #0d0d1a;\r\n    padding: 18px 16px;\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 14px;\r\n    overflow-y: auto;\r\n    overflow-x: hidden;\r\n    max-height: 100%;\r\n  }\r\n\r\n  .npx-info-section::-webkit-scrollbar {\r\n    width: 4px;\r\n  }\r\n\r\n  .npx-info-section::-webkit-scrollbar-track {\r\n    background: transparent;\r\n  }\r\n\r\n  .npx-info-section::-webkit-scrollbar-thumb {\r\n    background: rgba(255, 255, 255, 0.1);\r\n    border-radius: 4px;\r\n  }\r\n\r\n  .npx-video-meta {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 4px;\r\n  }\r\n\r\n  .npx-video-meta h3 {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: 14px;\r\n    color: #fff;\r\n    line-height: 1.4;\r\n  }\r\n\r\n  .npx-video-meta .npx-handle {\r\n    font-size: 11px;\r\n    color: var(--npx-acc2);\r\n  }\r\n\r\n  .npx-stat-row {\r\n    display: flex;\r\n    gap: 8px;\r\n    flex-wrap: wrap;\r\n  }\r\n\r\n  .npx-stat-chip {\r\n    background: rgba(255, 255, 255, 0.05);\r\n    border: 1px solid rgba(255, 255, 255, 0.08);\r\n    border-radius: 8px;\r\n    padding: 6px 10px;\r\n    display: flex;\r\n    flex-direction: column;\r\n    align-items: center;\r\n    gap: 1px;\r\n    flex: 1;\r\n    min-width: 52px;\r\n  }\r\n\r\n  .npx-stat-chip .npx-val {\r\n    font-size: 13px;\r\n    font-weight: 500;\r\n    color: #fff;\r\n  }\r\n\r\n  .npx-stat-chip .npx-lbl {\r\n    font-size: 9px;\r\n    color: var(--npx-muted);\r\n    text-transform: uppercase;\r\n    letter-spacing: 0.8px;\r\n  }\r\n\r\n  .npx-caption-box {\r\n    background: rgba(255, 255, 255, 0.03);\r\n    border: 1px solid rgba(255, 255, 255, 0.06);\r\n    border-radius: 10px;\r\n    padding: 10px;\r\n  }\r\n\r\n  .npx-caption-box p {\r\n    font-size: 11px;\r\n    color: rgba(255, 255, 255, 0.55);\r\n    line-height: 1.7;\r\n  }\r\n\r\n  .npx-caption-box .npx-hashtags {\r\n    margin-top: 6px;\r\n    display: flex;\r\n    flex-wrap: wrap;\r\n    gap: 4px;\r\n  }\r\n\r\n  .npx-hashtag {\r\n    font-size: 10px;\r\n    color: var(--npx-acc2);\r\n    background: rgba(245, 166, 35, 0.08);\r\n    border: 1px solid rgba(245, 166, 35, 0.15);\r\n    border-radius: 6px;\r\n    padding: 2px 7px;\r\n  }\r\n\r\n  .npx-related-title {\r\n    font-size: 10px;\r\n    text-transform: uppercase;\r\n    letter-spacing: 1px;\r\n    color: var(--npx-muted);\r\n  }\r\n\r\n  .npx-related-list {\r\n    display: flex;\r\n    flex-direction: row;\r\n    gap: 12px;\r\n    overflow-x: auto;\r\n    scroll-behavior: smooth;\r\n    scroll-snap-type: x mandatory;\r\n    padding-bottom: 8px;\r\n  }\r\n\r\n  .npx-related-list::-webkit-scrollbar {\r\n    height: 4px;\r\n  }\r\n\r\n  .npx-related-list::-webkit-scrollbar-track {\r\n    background: rgba(255, 255, 255, 0.05);\r\n    border-radius: 4px;\r\n  }\r\n\r\n  .npx-related-list::-webkit-scrollbar-thumb {\r\n    background: rgba(255, 255, 255, 0.2);\r\n    border-radius: 4px;\r\n  }\r\n\r\n  .npx-related-item {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 6px;\r\n    align-items: stretch;\r\n    padding: 6px;\r\n    border-radius: 8px;\r\n    background: rgba(255, 255, 255, 0.03);\r\n    border: 1px solid rgba(255, 255, 255, 0.05);\r\n    cursor: pointer;\r\n    transition: background 0.15s, transform 0.15s;\r\n    flex: 0 0 90px;\r\n    scroll-snap-align: start;\r\n  }\r\n\r\n  .npx-related-item:hover {\r\n    background: rgba(255, 255, 255, 0.07);\r\n    transform: translateY(-2px);\r\n  }\r\n\r\n  .npx-related-thumb {\r\n    width: 100%;\r\n    height: 138px;\r\n    border-radius: 4px;\r\n    background: linear-gradient(135deg, #1a1a3e, #0f3460);\r\n    flex-shrink: 0;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    overflow: hidden;\r\n  }\r\n\r\n  .npx-related-thumb svg {\r\n    width: 14px;\r\n    height: 14px;\r\n    fill: rgba(255, 255, 255, 0.4);\r\n  }\r\n\r\n  .npx-related-info p {\r\n    font-size: 10px;\r\n    color: rgba(255, 255, 255, 0.7);\r\n    line-height: 1.3;\r\n    white-space: nowrap;\r\n    overflow: hidden;\r\n    text-overflow: ellipsis;\r\n  }\r\n\r\n  .npx-related-info span {\r\n    font-size: 10px;\r\n    color: var(--npx-muted);\r\n  }\r\n\r\n  .npx-right-panel {\r\n    background: linear-gradient(160deg, #0a0a18 0%, #0f1a35 50%, #0a0a18 100%);\r\n    padding: 30px 20px;\r\n    display: block;\r\n    text-align: center;\r\n    min-width: 250px;\r\n    position: relative;\r\n  }\r\n\r\n  .npx-right-panel::before {\r\n    content: \'\';\r\n    position: absolute;\r\n    top: -60px;\r\n    left: 50%;\r\n    transform: translateX(-50%);\r\n    width: 180px;\r\n    height: 180px;\r\n    border-radius: 50%;\r\n    background: radial-gradient(circle, rgba(233, 69, 96, 0.12), transparent 70%);\r\n    pointer-events: none;\r\n  }\r\n\r\n  .npx-appt-top {\r\n    display: flex;\r\n    flex-direction: column;\r\n    align-items: center;\r\n    gap: 12px;\r\n    padding-top: 8px;\r\n    margin-bottom: 24px;\r\n  }\r\n\r\n  .npx-appt-icon {\r\n    width: 52px;\r\n    height: 52px;\r\n    border-radius: 16px;\r\n    background: rgba(233, 69, 96, 0.12);\r\n    border: 1px solid rgba(233, 69, 96, 0.25);\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n  }\r\n\r\n  .npx-appt-icon svg {\r\n    width: 26px;\r\n    height: 26px;\r\n    fill: var(--npx-acc);\r\n  }\r\n\r\n  .npx-appt-title {\r\n    font-family: \'Playfair Display\', serif;\r\n    font-size: 15px;\r\n    color: #fff;\r\n    line-height: 1.4;\r\n  }\r\n\r\n  .npx-appt-sub {\r\n    font-size: 11px;\r\n    color: var(--npx-muted);\r\n    line-height: 1.6;\r\n  }\r\n\r\n  .npx-appt-features {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 7px;\r\n    width: 100%;\r\n    margin-bottom: 24px;\r\n  }\r\n\r\n  .npx-appt-feat {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 8px;\r\n    font-size: 11px;\r\n    color: rgba(255, 255, 255, 0.6);\r\n  }\r\n\r\n  .npx-feat-dot {\r\n    width: 5px;\r\n    height: 5px;\r\n    border-radius: 50%;\r\n    background: var(--npx-acc2);\r\n    flex-shrink: 0;\r\n  }\r\n\r\n  .npx-slots-preview {\r\n    width: 100%;\r\n    background: rgba(255, 255, 255, 0.03);\r\n    border: 1px solid rgba(255, 255, 255, 0.07);\r\n    border-radius: 10px;\r\n    padding: 10px;\r\n    margin-bottom: 24px;\r\n  }\r\n\r\n  .npx-slots-label {\r\n    font-size: 9px;\r\n    color: var(--npx-muted);\r\n    text-transform: uppercase;\r\n    letter-spacing: 1px;\r\n    margin-bottom: 6px;\r\n  }\r\n\r\n  .npx-slot-pills {\r\n    display: flex;\r\n    flex-wrap: wrap;\r\n    gap: 4px;\r\n  }\r\n\r\n  .npx-slot-pill {\r\n    font-size: 10px;\r\n    padding: 3px 8px;\r\n    border-radius: 6px;\r\n    border: 1px solid rgba(255, 255, 255, 0.1);\r\n    color: rgba(255, 255, 255, 0.5);\r\n    transition: all 0.2s ease;\r\n  }\r\n\r\n  .npx-slot-pill.npx-avail {\r\n    border-color: rgba(15, 180, 100, 0.3);\r\n    color: rgba(15, 200, 120, 0.8);\r\n    background: rgba(15, 180, 100, 0.07);\r\n    cursor: pointer;\r\n  }\r\n\r\n  .npx-slot-pill.npx-avail:hover {\r\n    background: rgba(15, 180, 100, 0.15);\r\n    border-color: rgba(15, 180, 100, 0.5);\r\n    transform: translateY(-1px);\r\n  }\r\n\r\n  .npx-slot-pill.npx-avail.npx-selected {\r\n    background: var(--npx-acc);\r\n    border-color: var(--npx-acc);\r\n    color: #fff;\r\n    box-shadow: 0 4px 10px rgba(233, 69, 96, 0.3);\r\n  }\r\n\r\n  .npx-appt-btn {\r\n    width: 100%;\r\n    background: var(--npx-acc);\r\n    color: #fff;\r\n    border: none;\r\n    border-radius: 12px;\r\n    padding: 13px;\r\n    font-size: 13px;\r\n    font-weight: 500;\r\n    font-family: \'DM Sans\', sans-serif;\r\n    cursor: pointer;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    gap: 7px;\r\n    transition: transform 0.15s, opacity 0.15s;\r\n    letter-spacing: 0.2px;\r\n  }\r\n\r\n  .npx-appt-btn:hover {\r\n    opacity: 0.9;\r\n    transform: translateY(-1px);\r\n  }\r\n\r\n  .npx-appt-btn:active {\r\n    transform: scale(0.98);\r\n  }\r\n\r\n  .npx-appt-btn svg {\r\n    width: 16px;\r\n    height: 16px;\r\n    fill: #fff;\r\n  }\r\n\r\n  .npx-appt-note {\r\n    font-size: 10px;\r\n    color: rgba(255, 255, 255, 0.25);\r\n    line-height: 1.5;\r\n  }\r\n\r\n  @media (max-width: 850px) {\r\n    .npx-popup-body {\r\n      grid-template-columns: 1fr;\r\n    }\r\n\r\n    .npx-left-panel {\r\n      grid-template-columns: 1fr;\r\n      border-right: none;\r\n      border-bottom: 1px solid rgba(255, 255, 255, 0.07);\r\n    }\r\n\r\n    .npx-popup-overlay {\r\n      height: 90vh;\r\n      overflow-y: auto;\r\n      max-width: 95vw;\r\n    }\r\n\r\n    .npx-right-panel {\r\n      padding: 30px 16px;\r\n      gap: 20px;\r\n    }\r\n\r\n    .npx-reel-frame {\r\n      width: 100%;\r\n      height: 100%;\r\n    }\r\n  }\r\n</style>\r\n\r\n<h2 class=\"npx-sr-only\"\r\n  style=\"position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border-width:0;\">\r\n  Latest news popup with Instagram reel viewer and appointment booking</h2>\r\n\r\n<div class=\"npx-popup-backdrop\" id=\"npxPopupBackdrop\">\r\n  <div class=\"npx-popup-overlay\">\r\n\r\n    <div class=\"npx-popup-body\">\r\n\r\n      <div class=\"npx-left-panel\">\r\n\r\n        <!-- INSTAGRAM REEL SIDE -->\r\n        <div class=\"npx-reel-section\" style=\"justify-content: center; padding: 0;\">\r\n          <div class=\"npx-reel-frame\" id=\"npxReelFrame\"\r\n            style=\"height: 100%; border-radius: 0; border-right: 1px solid rgba(255, 255, 255, 0.08); overflow: hidden;\">\r\n\r\n            <!-- VIDEO SKELETON LOADER -->\r\n            <div id=\"npxVideoSkeleton\"\r\n              style=\"width: 100%; height: 100%; background: rgba(255, 255, 255, 0.05); animation: npxPulse 1.5s infinite ease-in-out;\">\r\n            </div>\r\n\r\n            <video id=\"npxMainVideo\"\r\n              src=\"https://instagram.fdel1-7.fna.fbcdn.net/o1/v/t2/f2/m86/AQO5sIiKbPw1xkABk9k7Sl_Og_DC_-z2-XmV5EQV3OgwjGuIKWMDSfwNTegQ460MWu4uT421GlSfFsw3STzmfFxVlb8wmNWzjzQZtsk.mp4?_nc_cat=103&_nc_oc=AdpOCAB9FAiyBIZdm03WcZKCyDNMZimduxyi3ul9tcJ_69injBOV6gd5WZNfL-cUH1PD8tkVo4gjACEu9bfhaxbE&_nc_sid=5e9851&_nc_ht=instagram.fdel1-7.fna.fbcdn.net&_nc_ohc=2kLsowPX0VIQ7kNvwGI-9AF&efg=eyJ2ZW5jb2RlX3RhZyI6Inhwdl9wcm9ncmVzc2l2ZS5JTlNUQUdSQU0uQ0xJUFMuQzMuNzIwLmRhc2hfYmFzZWxpbmVfMV92MSIsInhwdl9hc3NldF9pZCI6MTc5MTM3NTM1MTMzNjQ3NDMsImFzc2V0X2FnZV9kYXlzIjozLCJ2aV91c2VjYXNlX2lkIjoxMDA5OSwiZHVyYXRpb25fcyI6ODksInVybGdlbl9zb3VyY2UiOiJ3d3cifQ%3D%3D&ccb=17-1&vs=35508edcd865211d&_nc_&_nc_gid=6zF1FeT4mOtd7D9M4acWzQ&edm=ANQ71j8EAAAA&_nc_zt=28&_nc_tpa=Q5bMBQFJGIg9ypkpDPIyibfpxGJZt8I1UOMdB18a0nq1rOQFPJC6F7KDgXEcl-GwAw5Ch2jFKjcF6JrlzA&oh=00_Af3iKm-2V2vnHbFsJZ-giGoqYRj24U_N5c59J6pGZhMytQ&oe=69F10D18\"\r\n              poster=\"https://scontent.cdninstagram.com/v/t51.82787-15/672336940_17913753534364743_7989516135913121464_n.jpg?stp=dst-jpg_e35_tt6&_nc_cat=102&ccb=7-5&_nc_sid=18de74&efg=eyJlZmdfdGFnIjoiQ0xJUFMuYmVzdF9pbWFnZV91cmxnZW4uQzMifQ%3D%3D&_nc_ohc=1zhwq2Ng-t4Q7kNvwGoLkpr&_nc_oc=AdqSGR7_l5tiEmor48v7M2-AxPD3H2aoaZ-WWkrbEq1zXTWvnfBLU6wkpYqm3NBU_dn6XUdf69SQp8z-T55IqcA1&_nc_zt=23&_nc_ht=scontent.cdninstagram.com&edm=ANQ71j8EAAAA&_nc_gid=6zF1FeT4mOtd7D9M4acWzQ&_nc_tpa=Q5bMBQFJYeYe5YUHF-FncYjnzEpzJTheHmoL-2pSw_HC84XlYIo95YvJ4UqQOK_iRLcCAdT4hwvMxU5Y7A&oh=00_Af3xIWfHQhnu5gVWWjdKwZpbyX8uYo7isef6bvvWBfdz5A&oe=69F515FA\"\r\n              style=\"display: none; width: 100%; height: 100%; object-fit: cover; cursor: pointer;\" autoplay loop\r\n              playsinline referrerpolicy=\"no-referrer\" onclick=\"this.muted = !this.muted\" title=\"Click to toggle sound\">\r\n            </video>\r\n          </div>\r\n\r\n          <!-- <div class=\"npx-token-form\">\r\n            <label>Instagram Access Token</label>\r\n            <input type=\"text\" id=\"npxIgToken\" placeholder=\"EAABs...\" />\r\n            <input type=\"text\" id=\"npxMediaId\" placeholder=\"Media ID or Reel URL\" style=\"margin-top:4px\" />\r\n            <button onclick=\"npxLoadReel()\">Load Reel</button>\r\n          </div> -->\r\n        </div>\r\n\r\n        <!-- VIDEO INFO SIDE -->\r\n        <div class=\"npx-info-section\">\r\n\r\n          <!-- SKELETON LOADER -->\r\n          <div class=\"npx-skeleton\" id=\"npxSkeleton\">\r\n            <div class=\"npx-skel-line\" style=\"width: 40%; height: 16px; margin-bottom: 20px;\"></div>\r\n            <div class=\"npx-skel-line\" style=\"width: 80%; height: 24px; margin-bottom: 8px;\"></div>\r\n            <div class=\"npx-skel-line\" style=\"width: 30%; height: 14px; margin-bottom: 20px;\"></div>\r\n            <div style=\"display: flex; gap: 8px; margin-bottom: 20px;\">\r\n              <div class=\"npx-skel-line\" style=\"flex: 1; height: 36px;\"></div>\r\n              <div class=\"npx-skel-line\" style=\"flex: 1; height: 36px;\"></div>\r\n              <div class=\"npx-skel-line\" style=\"flex: 1; height: 36px;\"></div>\r\n            </div>\r\n            <div class=\"npx-skel-line\" style=\"width: 100%; height: 60px; margin-bottom: 20px;\"></div>\r\n            <div class=\"npx-skel-line\" style=\"width: 50%; height: 16px; margin-bottom: 12px;\"></div>\r\n            <div style=\"display: flex; gap: 12px; overflow: hidden;\">\r\n              <div class=\"npx-skel-line\" style=\"min-width: 90px; height: 140px; border-radius: 8px;\"></div>\r\n              <div class=\"npx-skel-line\" style=\"min-width: 90px; height: 140px; border-radius: 8px;\"></div>\r\n              <div class=\"npx-skel-line\" style=\"min-width: 90px; height: 140px; border-radius: 8px;\"></div>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- ACTUAL CONTENT -->\r\n          <div id=\"npxInfoContent\" style=\"display: none; flex-direction: column; gap: 14px; width: 100%;\">\r\n            <div class=\"npx-section-label\">\r\n              <svg viewBox=\"0 0 24 24\">\r\n                <path d=\"M13 2.003A10 10 0 1 0 22 12 10 10 0 0 0 13 2.003zm-1 14.5v-9l6 4.5z\" />\r\n              </svg>\r\n              Video Info\r\n            </div>\r\n\r\n            <div class=\"npx-video-meta\" id=\"npxVideoMeta\">\r\n              <h3>Call Sirf 11.00 Baje Se Shaam 6.00 Baje Tak hi kare</h3>\r\n              <span class=\"npx-handle\">@avisaexperts</span>\r\n            </div>\r\n\r\n            <div class=\"npx-stat-row\">\r\n              <div class=\"npx-stat-chip\"><span class=\"npx-val\" id=\"npxStatViews\">12K</span><span\r\n                  class=\"npx-lbl\">Views</span></div>\r\n              <div class=\"npx-stat-chip\"><span class=\"npx-val\" id=\"npxStatLikes\">850</span><span\r\n                  class=\"npx-lbl\">Likes</span></div>\r\n              <div class=\"npx-stat-chip\"><span class=\"npx-val\" id=\"npxStatComments\">124</span><span\r\n                  class=\"npx-lbl\">Comments</span></div>\r\n            </div>\r\n\r\n            <div class=\"npx-caption-box\">\r\n              <p id=\"npxCaptionText\">Call Sirf 11.00 Baje Se Shaam 6.00 Baje Tak hi kare</p>\r\n              <div class=\"npx-hashtags\">\r\n                <span class=\"npx-hashtag\">#viralvideos</span>\r\n                <span class=\"npx-hashtag\">#visa</span>\r\n                <span class=\"npx-hashtag\">#famous</span>\r\n                <span class=\"npx-hashtag\">#avisaexperts</span>\r\n                <span class=\"npx-hashtag\">#kaveeshkapoor</span>\r\n              </div>\r\n            </div>\r\n\r\n            <div>\r\n              <p class=\"npx-related-title\">More from this creator</p>\r\n              <div class=\"npx-related-list\">\r\n                <!-- Hardcoded reels will be replaced by JS -->\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n      </div>\r\n\r\n      <!-- RIGHT: BOOK APPOINTMENT -->\r\n      <div class=\"npx-right-panel\">\r\n\r\n        <div class=\"npx-appt-top\">\r\n          <div class=\"npx-appt-icon\">\r\n            <svg viewBox=\"0 0 24 24\">\r\n              <path\r\n                d=\"M19 4h-1V2h-2v2H8V2H6v2H5c-1.11 0-2 .89-2 2v14c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2V6c0-1.11-.9-2-2-2zm0 16H5V10h14v10zm0-12H5V6h14v2zM7 12h5v5H7z\" />\r\n            </svg>\r\n          </div>\r\n          <div>\r\n            <p class=\"npx-appt-title\">Book a<br />Consultation</p>\r\n            <p class=\"npx-appt-sub\">Talk to an expert.<br />Free 30-min session.</p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"npx-appt-features\">\r\n          <div class=\"npx-appt-feat\"><span class=\"npx-feat-dot\"></span>Choose your preferred time</div>\r\n          <div class=\"npx-appt-feat\"><span class=\"npx-feat-dot\"></span>Video or in-person meeting</div>\r\n          <div class=\"npx-appt-feat\"><span class=\"npx-feat-dot\"></span>Instant confirmation</div>\r\n          <div class=\"npx-appt-feat\"><span class=\"npx-feat-dot\"></span>No payment required</div>\r\n        </div>\r\n\r\n        <div class=\"npx-slots-preview\">\r\n          <p class=\"npx-slots-label\">Available Today</p>\r\n          <div class=\"npx-slot-pills\">\r\n            <span class=\"npx-slot-pill npx-avail\" onclick=\"npxSelectSlot(this)\">10:00 AM</span>\r\n            <span class=\"npx-slot-pill\" title=\"Not available\">11:30 AM</span>\r\n            <span class=\"npx-slot-pill npx-avail\" onclick=\"npxSelectSlot(this)\">2:00 PM</span>\r\n            <span class=\"npx-slot-pill npx-avail\" onclick=\"npxSelectSlot(this)\">4:30 PM</span>\r\n            <span class=\"npx-slot-pill\" title=\"Not available\">6:00 PM</span>\r\n          </div>\r\n        </div>\r\n\r\n        <div style=\"width:100%;display:flex;flex-direction:column;gap:8px\">\r\n          <button class=\"npx-appt-btn\" onclick=\"npxOpenLink(\'https://yoursite.com/book-appointment\')\">\r\n            <svg viewBox=\"0 0 24 24\">\r\n              <path\r\n                d=\"M19 4h-1V2h-2v2H8V2H6v2H5c-1.11 0-2 .89-2 2v14c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2V6c0-1.11-.9-2-2-2zm0 16H5V10h14v10z\" />\r\n            </svg>\r\n            Book Appointment\r\n          </button>\r\n          <p class=\"npx-appt-note\">Opens full booking page in a new tab</p>\r\n        </div>\r\n\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<script>\r\n  // ==========================================\r\n  // DYNAMIC INSTAGRAM FETCHING LOGIC\r\n  // ==========================================\r\n  const IG_CONFIG = {\r\n    // ⚠️ Replace this with your actual Instagram Access Token\r\n    accessToken: \'IGAAWp7Lk0ae5BZAFptTGlwY0o0VkxMdm5mNU5vcWR5WnJnVXJfMTFQWFhUaUVJdmpteUszU082dTZAGWm9OTzhlUndITDRPTXJuTXpVLTlvOHZADcFhnbGFGVmM5Uk9Ja2FQVlloYURHWnc1czg2SGVmdlE4anJpOEwtdmFHaUptZAwZDZD\',\r\n    limit: 5 // How many posts to fetch\r\n  };\r\n\r\n  function showInfoContent() {\r\n    // Right panel\r\n    const skel = document.getElementById(\'npxSkeleton\');\r\n    const cont = document.getElementById(\'npxInfoContent\');\r\n    if (skel) skel.style.display = \'none\';\r\n    if (cont) cont.style.display = \'flex\';\r\n\r\n    // Left panel video\r\n    const vidSkel = document.getElementById(\'npxVideoSkeleton\');\r\n    const mainVid = document.getElementById(\'npxMainVideo\');\r\n    if (vidSkel) vidSkel.style.display = \'none\';\r\n    if (mainVid) mainVid.style.display = \'block\';\r\n  }\r\n\r\n  async function fetchLatestReels() {\r\n    if (!IG_CONFIG.accessToken || IG_CONFIG.accessToken === \'YOUR_INSTAGRAM_ACCESS_TOKEN\') {\r\n      console.warn(\'Instagram Access Token missing. Using hardcoded static reels as fallback.\');\r\n      showInfoContent();\r\n      return;\r\n    }\r\n\r\n    try {\r\n      // Fetch media from Instagram Graph API\r\n      const response = await fetch(`https://graph.instagram.com/me/media?fields=id,caption,media_type,media_url,thumbnail_url,timestamp&limit=${IG_CONFIG.limit}&access_token=${IG_CONFIG.accessToken}`);\r\n      const data = await response.json();\r\n\r\n      if (data.error) {\r\n        console.error(\'Error fetching Instagram data:\', data.error.message);\r\n        showInfoContent();\r\n        return;\r\n      }\r\n\r\n      // Filter only videos (reels)\r\n      const reels = data.data.filter(item => item.media_type === \'VIDEO\');\r\n\r\n      if (reels.length > 0) {\r\n        populateReelsUI(reels);\r\n        showInfoContent();\r\n      } else {\r\n        showInfoContent();\r\n      }\r\n    } catch (error) {\r\n      console.error(\'Network error fetching reels:\', error);\r\n      showInfoContent();\r\n    }\r\n  }\r\n\r\n  function populateReelsUI(reels) {\r\n    const listContainer = document.querySelector(\'.npx-related-list\');\r\n    listContainer.innerHTML = \'\'; // Clear hardcoded reels\r\n\r\n    reels.forEach((reel, index) => {\r\n      // Create thumbnail HTML\r\n      const thumbUrl = reel.thumbnail_url || \'\';\r\n      let title = (reel.caption || \'\').replace(/#\\w+/g, \'\').trim();\r\n      if (title.length > 20) title = title.substring(0, 20) + \'...\';\r\n      if (!title) title = \'Instagram Reel\';\r\n\r\n      const itemHtml = `\r\n        <div class=\"npx-related-item\"\r\n          data-media=\"${reel.media_url}\"\r\n          data-poster=\"${thumbUrl}\"\r\n          data-caption=\"${(reel.caption || \'\').replace(/\"/g, \'&quot;\')}\"\r\n          onclick=\"npxChangeReel(this)\">\r\n          <div class=\"npx-related-thumb\" style=\"padding:0; overflow:hidden;\">\r\n            ${thumbUrl ? `<img src=\"${thumbUrl}\" style=\"width:100%;height:100%;object-fit:cover;\" referrerpolicy=\"no-referrer\" />` : \'\'}\r\n          </div>\r\n          <div class=\"npx-related-info\" style=\"min-width:0;\">\r\n            <p style=\"white-space:nowrap;overflow:hidden;text-overflow:ellipsis;\">${title}</p>\r\n            <span>Play Reel</span>\r\n          </div>\r\n        </div>\r\n      `;\r\n      listContainer.innerHTML += itemHtml;\r\n\r\n      // Automatically load the first reel into the main viewer\r\n      if (index === 0) {\r\n        // Find the newly added element and trigger click\r\n        const firstReelEl = listContainer.querySelector(\'.npx-related-item\');\r\n        if (firstReelEl) npxChangeReel(firstReelEl);\r\n      }\r\n    });\r\n  }\r\n\r\n  // Fetch reels when page loads\r\n  document.addEventListener(\'DOMContentLoaded\', fetchLatestReels);\r\n\r\n  // ==========================================\r\n  // EXISTING FUNCTIONS\r\n  // ==========================================\r\n  function npxLoadReel() {\r\n    const token = document.getElementById(\'npxIgToken\').value.trim();\r\n    const mediaId = document.getElementById(\'npxMediaId\').value.trim();\r\n    const frame = document.getElementById(\'npxReelFrame\');\r\n    const placeholder = document.getElementById(\'npxReelPlaceholder\');\r\n\r\n    if (!token || !mediaId) {\r\n      placeholder.querySelector(\'span\').textContent = \'Please enter both token and media ID.\';\r\n      return;\r\n    }\r\n\r\n    placeholder.querySelector(\'span\').textContent = \'Loading reel...\';\r\n\r\n    const existing = frame.querySelector(\'iframe\');\r\n    if (existing) existing.remove();\r\n\r\n    const url = `https://www.instagram.com/p/${mediaId}/embed/`;\r\n    const iframe = document.createElement(\'iframe\');\r\n    iframe.src = url;\r\n    iframe.style.cssText = \'width:100%;height:100%;border:none;border-radius:14px;\';\r\n    iframe.allow = \'autoplay; encrypted-media\';\r\n    iframe.onload = () => { placeholder.style.display = \'none\'; };\r\n    iframe.onerror = () => { placeholder.querySelector(\'span\').textContent = \'Could not load reel. Check your media ID.\'; };\r\n    frame.insertBefore(iframe, frame.querySelector(\'.npx-play-btn\'));\r\n  }\r\n\r\n  function npxOpenLink(url) {\r\n    window.open(url, \'_blank\');\r\n  }\r\n\r\n  function npxSelectSlot(element) {\r\n    document.querySelectorAll(\'.npx-slot-pill.npx-avail\').forEach(el => {\r\n      el.classList.remove(\'npx-selected\');\r\n    });\r\n    element.classList.add(\'npx-selected\');\r\n\r\n    const btn = document.querySelector(\'.npx-appt-btn\');\r\n    btn.innerHTML = \'<svg viewBox=\"0 0 24 24\"><path d=\"M19 4h-1V2h-2v2H8V2H6v2H5c-1.11 0-2 .89-2 2v14c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2V6c0-1.11-.9-2-2-2zm0 16H5V10h14v10z\"/></svg> Book for \' + element.innerText;\r\n  }\r\n\r\n  function npxChangeReel(element) {\r\n    const media = element.getAttribute(\'data-media\');\r\n    const poster = element.getAttribute(\'data-poster\');\r\n    const captionRaw = element.getAttribute(\'data-caption\') || \'Instagram Reel\';\r\n\r\n    // Update video source\r\n    const video = document.querySelector(\'#npxReelFrame video\');\r\n    video.src = media;\r\n    video.poster = poster;\r\n    video.load();\r\n\r\n    // 1. Try to play with sound ON by default\r\n    video.muted = false;\r\n\r\n    video.play().catch(e => {\r\n      console.log(\'Browser blocked autoplay with sound. Falling back to muted autoplay.\');\r\n      // 2. If the browser blocks it (because the user hasn\'t clicked anything yet), \r\n      //    fallback to playing it muted so the video at least plays.\r\n      video.muted = true;\r\n      video.play().catch(err => console.log(\'Autoplay completely blocked:\', err));\r\n    });\r\n\r\n    // Parse caption and hashtags\r\n    let title = captionRaw.replace(/#\\w+/g, \'\').trim();\r\n    if (title.length > 65) title = title.substring(0, 65) + \'...\';\r\n    if (title.length === 0) title = \'Instagram Reel\';\r\n\r\n    document.querySelector(\'#npxVideoMeta h3\').innerText = title;\r\n    document.getElementById(\'npxCaptionText\').innerText = captionRaw.replace(/#\\w+/g, \'\').trim();\r\n\r\n    // Extract hashtags and update UI\r\n    const hashtags = captionRaw.match(/#\\w+/g) || [];\r\n    const tagsHtml = hashtags.map(t => `<span class=\"npx-hashtag\">${t}</span>`).join(\'\');\r\n    document.querySelector(\'.npx-hashtags\').innerHTML = tagsHtml;\r\n\r\n    // Randomize stats slightly to feel dynamic\r\n    document.getElementById(\'npxStatViews\').innerText = Math.floor(Math.random() * 50 + 5) + \'K\';\r\n    document.getElementById(\'npxStatLikes\').innerText = Math.floor(Math.random() * 900 + 100);\r\n    document.getElementById(\'npxStatComments\').innerText = Math.floor(Math.random() * 150 + 10);\r\n  }\r\n</script>', '2026-05-01 07:50:36');
INSERT INTO `banner_code_snapshot` (`id`, `code_content`, `created_at`) VALUES
(75, '<style>\n  @import url(\'https://fonts.googleapis.com/css2?family=Playfair+Display:wght@600;700&family=DM+Sans:wght@300;400;500&display=swap\');\n\n  :root {\n    --npx-c1: #0f0f0f;\n    --npx-c2: #1a1a2e;\n    --npx-c3: #16213e;\n    --npx-c4: #0f3460;\n    --npx-acc: #e94560;\n    --npx-acc2: #f5a623;\n    --npx-light: #f8f4ef;\n    --npx-muted: #a0a0b0;\n  }\n\n  .npx-popup-backdrop,\n  .npx-popup-backdrop * {\n    box-sizing: border-box;\n    margin: 0;\n    padding: 0;\n  }\n\n  .npx-popup-backdrop {\n    font-family: \'DM Sans\', sans-serif;\n    /* position: fixed; */\n    top: 0;\n    left: 0;\n    /* width: 100vw;\n    height: 100vh; */\n    background: rgba(0, 0, 0, 0.75);\n    backdrop-filter: blur(8px);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    z-index: 9999;\n    /* padding: 20px; */\n  }\n\n  .npx-popup-overlay {\n    background: rgba(10, 10, 20, 0.92);\n    border-radius: 20px;\n    overflow: hidden;\n    display: flex;\n    flex-direction: column;\n    min-height: 580px;\n    width: 100%;\n    max-width: 900px;\n    border: 1px solid rgba(255, 255, 255, 0.08);\n    position: relative;\n    box-shadow: 0 30px 60px rgba(0, 0, 0, 0.5);\n    animation: npxPopIn 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;\n  }\n\n  @keyframes npxPopIn {\n    0% {\n      opacity: 0;\n      transform: scale(0.9) translateY(20px);\n    }\n\n    100% {\n      opacity: 1;\n      transform: scale(1) translateY(0);\n    }\n  }\n\n  .npx-skeleton {\n    display: flex;\n    flex-direction: column;\n    width: 100%;\n    gap: 12px;\n    animation: npxPulse 1.5s infinite ease-in-out;\n  }\n\n  .npx-skel-line {\n    background: rgba(255, 255, 255, 0.08);\n    border-radius: 6px;\n  }\n\n  @keyframes npxPulse {\n    0% {\n      opacity: 0.5;\n    }\n\n    50% {\n      opacity: 1;\n    }\n\n    100% {\n      opacity: 0.5;\n    }\n  }\n\n  .npx-popup-header {\n    background: linear-gradient(90deg, #0f3460, #16213e);\n    padding: 14px 22px;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    border-bottom: 1px solid rgba(255, 255, 255, 0.07);\n  }\n\n  .npx-popup-header h2 {\n    font-family: \'Playfair Display\', serif;\n    font-size: 17px;\n    color: #fff;\n    letter-spacing: 0.3px;\n  }\n\n  .npx-live-badge {\n    background: var(--npx-acc);\n    color: #fff;\n    font-size: 10px;\n    font-weight: 500;\n    padding: 3px 10px;\n    border-radius: 20px;\n    display: flex;\n    align-items: center;\n    gap: 5px;\n    letter-spacing: 0.5px;\n  }\n\n  .npx-live-dot {\n    width: 6px;\n    height: 6px;\n    border-radius: 50%;\n    background: #fff;\n    animation: npxBlink 1.2s infinite;\n  }\n\n  @keyframes npxBlink {\n\n    0%,\n    100% {\n      opacity: 1;\n    }\n\n    50% {\n      opacity: 0.2;\n    }\n  }\n\n  .npx-popup-close {\n    width: 28px;\n    height: 28px;\n    border-radius: 50%;\n    border: 1px solid rgba(255, 255, 255, 0.15);\n    background: rgba(255, 255, 255, 0.06);\n    color: #ccc;\n    font-size: 16px;\n    cursor: pointer;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    line-height: 1;\n  }\n\n  .npx-popup-body {\n    display: grid;\n    grid-template-columns: minmax(0, 2fr) minmax(260px, 1fr);\n    flex: 1;\n    min-height: 0;\n  }\n\n  .npx-left-panel {\n    display: grid;\n    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);\n    border-right: 1px solid rgba(255, 255, 255, 0.07);\n    min-width: 0;\n  }\n\n  .npx-reel-section {\n    background: #0a0a14;\n    padding: 18px 16px;\n    border-right: 1px solid rgba(255, 255, 255, 0.06);\n    display: flex;\n    flex-direction: column;\n    gap: 12px;\n  }\n\n  .npx-section-label {\n    font-size: 10px;\n    text-transform: uppercase;\n    letter-spacing: 1.5px;\n    color: var(--npx-muted);\n    display: flex;\n    align-items: center;\n    gap: 6px;\n  }\n\n  .npx-section-label svg {\n    width: 12px;\n    height: 12px;\n    fill: var(--npx-acc);\n  }\n\n  .npx-reel-frame {\n    background: #111;\n    border-radius: 14px;\n    overflow: hidden;\n    position: relative;\n    aspect-ratio: 9/14;\n    border: 1px solid rgba(255, 255, 255, 0.08);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    cursor: pointer;\n  }\n\n  .npx-reel-placeholder {\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 10px;\n    color: rgba(255, 255, 255, 0.3);\n  }\n\n  .npx-reel-placeholder svg {\n    width: 36px;\n    height: 36px;\n    opacity: 0.4;\n  }\n\n  .npx-reel-placeholder span {\n    font-size: 11px;\n    text-align: center;\n    max-width: 110px;\n    line-height: 1.5;\n  }\n\n  .npx-reel-frame .npx-play-btn {\n    width: 48px;\n    height: 48px;\n    border-radius: 50%;\n    background: rgba(233, 69, 96, 0.85);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    position: absolute;\n    bottom: 14px;\n    right: 14px;\n    cursor: pointer;\n    transition: transform 0.15s;\n  }\n\n  .npx-reel-frame .npx-play-btn:hover {\n    transform: scale(1.1);\n  }\n\n  .npx-play-btn svg {\n    width: 18px;\n    height: 18px;\n    fill: #fff;\n    margin-left: 2px;\n  }\n\n  .npx-token-form {\n    display: flex;\n    flex-direction: column;\n    gap: 6px;\n  }\n\n  .npx-token-form label {\n    font-size: 10px;\n    color: var(--npx-muted);\n    letter-spacing: 0.5px;\n  }\n\n  .npx-token-form input {\n    background: rgba(255, 255, 255, 0.05);\n    border: 1px solid rgba(255, 255, 255, 0.1);\n    border-radius: 8px;\n    color: #fff;\n    font-size: 11px;\n    padding: 7px 10px;\n    font-family: monospace;\n    outline: none;\n    width: 100%;\n    transition: border-color 0.2s;\n  }\n\n  .npx-token-form input:focus {\n    border-color: var(--npx-acc);\n  }\n\n  .npx-token-form button {\n    background: var(--npx-acc);\n    color: #fff;\n    border: none;\n    border-radius: 8px;\n    padding: 7px;\n    font-size: 11px;\n    font-family: \'DM Sans\', sans-serif;\n    cursor: pointer;\n    font-weight: 500;\n    transition: opacity 0.2s;\n    margin-top: 2px;\n  }\n\n  .npx-token-form button:hover {\n    opacity: 0.85;\n  }\n\n  .npx-info-section {\n    background: #0d0d1a;\n    padding: 18px 16px;\n    display: flex;\n    flex-direction: column;\n    gap: 14px;\n    overflow-y: auto;\n    overflow-x: hidden;\n    max-height: 100%;\n  }\n\n  .npx-info-section::-webkit-scrollbar {\n    width: 4px;\n  }\n\n  .npx-info-section::-webkit-scrollbar-track {\n    background: transparent;\n  }\n\n  .npx-info-section::-webkit-scrollbar-thumb {\n    background: rgba(255, 255, 255, 0.1);\n    border-radius: 4px;\n  }\n\n  .npx-video-meta {\n    display: flex;\n    flex-direction: column;\n    gap: 4px;\n  }\n\n  .npx-video-meta h3 {\n    font-family: \'Playfair Display\', serif;\n    font-size: 14px;\n    color: #fff;\n    line-height: 1.4;\n  }\n\n  .npx-video-meta .npx-handle {\n    font-size: 11px;\n    color: var(--npx-acc2);\n  }\n\n  .npx-stat-row {\n    display: flex;\n    gap: 8px;\n    flex-wrap: wrap;\n  }\n\n  .npx-stat-chip {\n    background: rgba(255, 255, 255, 0.05);\n    border: 1px solid rgba(255, 255, 255, 0.08);\n    border-radius: 8px;\n    padding: 6px 10px;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 1px;\n    flex: 1;\n    min-width: 52px;\n  }\n\n  .npx-stat-chip .npx-val {\n    font-size: 13px;\n    font-weight: 500;\n    color: #fff;\n  }\n\n  .npx-stat-chip .npx-lbl {\n    font-size: 9px;\n    color: var(--npx-muted);\n    text-transform: uppercase;\n    letter-spacing: 0.8px;\n  }\n\n  .npx-caption-box {\n    background: rgba(255, 255, 255, 0.03);\n    border: 1px solid rgba(255, 255, 255, 0.06);\n    border-radius: 10px;\n    padding: 10px;\n  }\n\n  .npx-caption-box p {\n    font-size: 11px;\n    color: rgba(255, 255, 255, 0.55);\n    line-height: 1.7;\n  }\n\n  .npx-caption-box .npx-hashtags {\n    margin-top: 6px;\n    display: flex;\n    flex-wrap: wrap;\n    gap: 4px;\n  }\n\n  .npx-hashtag {\n    font-size: 10px;\n    color: var(--npx-acc2);\n    background: rgba(245, 166, 35, 0.08);\n    border: 1px solid rgba(245, 166, 35, 0.15);\n    border-radius: 6px;\n    padding: 2px 7px;\n  }\n\n  .npx-related-title {\n    font-size: 10px;\n    text-transform: uppercase;\n    letter-spacing: 1px;\n    color: var(--npx-muted);\n  }\n\n  .npx-related-list {\n    display: flex;\n    flex-direction: row;\n    gap: 12px;\n    overflow-x: auto;\n    scroll-behavior: smooth;\n    scroll-snap-type: x mandatory;\n    padding-bottom: 8px;\n  }\n\n  .npx-related-list::-webkit-scrollbar {\n    height: 4px;\n  }\n\n  .npx-related-list::-webkit-scrollbar-track {\n    background: rgba(255, 255, 255, 0.05);\n    border-radius: 4px;\n  }\n\n  .npx-related-list::-webkit-scrollbar-thumb {\n    background: rgba(255, 255, 255, 0.2);\n    border-radius: 4px;\n  }\n\n  .npx-related-item {\n    display: flex;\n    flex-direction: column;\n    gap: 6px;\n    align-items: stretch;\n    padding: 6px;\n    border-radius: 8px;\n    background: rgba(255, 255, 255, 0.03);\n    border: 1px solid rgba(255, 255, 255, 0.05);\n    cursor: pointer;\n    transition: background 0.15s, transform 0.15s;\n    flex: 0 0 90px;\n    scroll-snap-align: start;\n  }\n\n  .npx-related-item:hover {\n    background: rgba(255, 255, 255, 0.07);\n    transform: translateY(-2px);\n  }\n\n  .npx-related-thumb {\n    width: 100%;\n    height: 138px;\n    border-radius: 4px;\n    background: linear-gradient(135deg, #1a1a3e, #0f3460);\n    flex-shrink: 0;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    overflow: hidden;\n  }\n\n  .npx-related-thumb svg {\n    width: 14px;\n    height: 14px;\n    fill: rgba(255, 255, 255, 0.4);\n  }\n\n  .npx-related-info p {\n    font-size: 10px;\n    color: rgba(255, 255, 255, 0.7);\n    line-height: 1.3;\n    white-space: nowrap;\n    overflow: hidden;\n    text-overflow: ellipsis;\n  }\n\n  .npx-related-info span {\n    font-size: 10px;\n    color: var(--npx-muted);\n  }\n\n  .npx-right-panel {\n    background: linear-gradient(160deg, #0a0a18 0%, #0f1a35 50%, #0a0a18 100%);\n    padding: 30px 20px;\n    display: block;\n    text-align: center;\n    min-width: 250px;\n    position: relative;\n  }\n\n  .npx-right-panel::before {\n    content: \'\';\n    position: absolute;\n    top: -60px;\n    left: 50%;\n    transform: translateX(-50%);\n    width: 180px;\n    height: 180px;\n    border-radius: 50%;\n    background: radial-gradient(circle, rgba(233, 69, 96, 0.12), transparent 70%);\n    pointer-events: none;\n  }\n\n  .npx-appt-top {\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 12px;\n    padding-top: 8px;\n    margin-bottom: 24px;\n  }\n\n  .npx-appt-icon {\n    width: 52px;\n    height: 52px;\n    border-radius: 16px;\n    background: rgba(233, 69, 96, 0.12);\n    border: 1px solid rgba(233, 69, 96, 0.25);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n\n  .npx-appt-icon svg {\n    width: 26px;\n    height: 26px;\n    fill: var(--npx-acc);\n  }\n\n  .npx-appt-title {\n    font-family: \'Playfair Display\', serif;\n    font-size: 15px;\n    color: #fff;\n    line-height: 1.4;\n  }\n\n  .npx-appt-sub {\n    font-size: 11px;\n    color: var(--npx-muted);\n    line-height: 1.6;\n  }\n\n  .npx-appt-features {\n    display: flex;\n    flex-direction: column;\n    gap: 7px;\n    width: 100%;\n    margin-bottom: 24px;\n  }\n\n  .npx-appt-feat {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    font-size: 11px;\n    color: rgba(255, 255, 255, 0.6);\n  }\n\n  .npx-feat-dot {\n    width: 5px;\n    height: 5px;\n    border-radius: 50%;\n    background: var(--npx-acc2);\n    flex-shrink: 0;\n  }\n\n  .npx-slots-preview {\n    width: 100%;\n    background: rgba(255, 255, 255, 0.03);\n    border: 1px solid rgba(255, 255, 255, 0.07);\n    border-radius: 10px;\n    padding: 10px;\n    margin-bottom: 24px;\n  }\n\n  .npx-slots-label {\n    font-size: 9px;\n    color: var(--npx-muted);\n    text-transform: uppercase;\n    letter-spacing: 1px;\n    margin-bottom: 6px;\n  }\n\n  .npx-slot-pills {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 4px;\n  }\n\n  .npx-slot-pill {\n    font-size: 10px;\n    padding: 3px 8px;\n    border-radius: 6px;\n    border: 1px solid rgba(255, 255, 255, 0.1);\n    color: rgba(255, 255, 255, 0.5);\n    transition: all 0.2s ease;\n  }\n\n  .npx-slot-pill.npx-avail {\n    border-color: rgba(15, 180, 100, 0.3);\n    color: rgba(15, 200, 120, 0.8);\n    background: rgba(15, 180, 100, 0.07);\n    cursor: pointer;\n  }\n\n  .npx-slot-pill.npx-avail:hover {\n    background: rgba(15, 180, 100, 0.15);\n    border-color: rgba(15, 180, 100, 0.5);\n    transform: translateY(-1px);\n  }\n\n  .npx-slot-pill.npx-avail.npx-selected {\n    background: var(--npx-acc);\n    border-color: var(--npx-acc);\n    color: #fff;\n    box-shadow: 0 4px 10px rgba(233, 69, 96, 0.3);\n  }\n\n  .npx-appt-btn {\n    width: 100%;\n    background: var(--npx-acc);\n    color: #fff;\n    border: none;\n    border-radius: 12px;\n    padding: 13px;\n    font-size: 13px;\n    font-weight: 500;\n    font-family: \'DM Sans\', sans-serif;\n    cursor: pointer;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    gap: 7px;\n    transition: transform 0.15s, opacity 0.15s;\n    letter-spacing: 0.2px;\n  }\n\n  .npx-appt-btn:hover {\n    opacity: 0.9;\n    transform: translateY(-1px);\n  }\n\n  .npx-appt-btn:active {\n    transform: scale(0.98);\n  }\n\n  .npx-appt-btn svg {\n    width: 16px;\n    height: 16px;\n    fill: #fff;\n  }\n\n  .npx-appt-note {\n    font-size: 10px;\n    color: rgba(255, 255, 255, 0.25);\n    line-height: 1.5;\n  }\n\n  @media (max-width: 850px) {\n    .npx-popup-body {\n      grid-template-columns: 1fr;\n    }\n\n    .npx-left-panel {\n      grid-template-columns: 1fr;\n      border-right: none;\n      border-bottom: 1px solid rgba(255, 255, 255, 0.07);\n    }\n\n    .npx-popup-overlay {\n      height: 90vh;\n      overflow-y: auto;\n      max-width: 95vw;\n    }\n\n    .npx-right-panel {\n      padding: 30px 16px;\n      gap: 20px;\n    }\n\n    .npx-reel-frame {\n      width: 100%;\n      height: 100%;\n    }\n  }\n</style>\n\n<h2 class=\"npx-sr-only\"\n  style=\"position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border-width:0;\">\n  Latest news popup with Instagram reel viewer and appointment booking</h2>\n\n<div class=\"npx-popup-backdrop\" id=\"npxPopupBackdrop\">\n  <div class=\"npx-popup-overlay\">\n\n    <div class=\"npx-popup-body\">\n\n      <div class=\"npx-left-panel\">\n\n        <!-- INSTAGRAM REEL SIDE -->\n        <div class=\"npx-reel-section\" style=\"justify-content: center; padding: 0;\">\n          <div class=\"npx-reel-frame\" id=\"npxReelFrame\"\n            style=\"height: 100%; border-radius: 0; border-right: 1px solid rgba(255, 255, 255, 0.08); overflow: hidden;\">\n\n            <!-- VIDEO SKELETON LOADER -->\n            <div id=\"npxVideoSkeleton\"\n              style=\"width: 100%; height: 100%; background: rgba(255, 255, 255, 0.05); animation: npxPulse 1.5s infinite ease-in-out;\">\n            </div>\n\n            <video id=\"npxMainVideo\"\n              src=\"https://instagram.fdel1-7.fna.fbcdn.net/o1/v/t2/f2/m86/AQO5sIiKbPw1xkABk9k7Sl_Og_DC_-z2-XmV5EQV3OgwjGuIKWMDSfwNTegQ460MWu4uT421GlSfFsw3STzmfFxVlb8wmNWzjzQZtsk.mp4?_nc_cat=103&_nc_oc=AdpOCAB9FAiyBIZdm03WcZKCyDNMZimduxyi3ul9tcJ_69injBOV6gd5WZNfL-cUH1PD8tkVo4gjACEu9bfhaxbE&_nc_sid=5e9851&_nc_ht=instagram.fdel1-7.fna.fbcdn.net&_nc_ohc=2kLsowPX0VIQ7kNvwGI-9AF&efg=eyJ2ZW5jb2RlX3RhZyI6Inhwdl9wcm9ncmVzc2l2ZS5JTlNUQUdSQU0uQ0xJUFMuQzMuNzIwLmRhc2hfYmFzZWxpbmVfMV92MSIsInhwdl9hc3NldF9pZCI6MTc5MTM3NTM1MTMzNjQ3NDMsImFzc2V0X2FnZV9kYXlzIjozLCJ2aV91c2VjYXNlX2lkIjoxMDA5OSwiZHVyYXRpb25fcyI6ODksInVybGdlbl9zb3VyY2UiOiJ3d3cifQ%3D%3D&ccb=17-1&vs=35508edcd865211d&_nc_&_nc_gid=6zF1FeT4mOtd7D9M4acWzQ&edm=ANQ71j8EAAAA&_nc_zt=28&_nc_tpa=Q5bMBQFJGIg9ypkpDPIyibfpxGJZt8I1UOMdB18a0nq1rOQFPJC6F7KDgXEcl-GwAw5Ch2jFKjcF6JrlzA&oh=00_Af3iKm-2V2vnHbFsJZ-giGoqYRj24U_N5c59J6pGZhMytQ&oe=69F10D18\"\n              poster=\"https://scontent.cdninstagram.com/v/t51.82787-15/672336940_17913753534364743_7989516135913121464_n.jpg?stp=dst-jpg_e35_tt6&_nc_cat=102&ccb=7-5&_nc_sid=18de74&efg=eyJlZmdfdGFnIjoiQ0xJUFMuYmVzdF9pbWFnZV91cmxnZW4uQzMifQ%3D%3D&_nc_ohc=1zhwq2Ng-t4Q7kNvwGoLkpr&_nc_oc=AdqSGR7_l5tiEmor48v7M2-AxPD3H2aoaZ-WWkrbEq1zXTWvnfBLU6wkpYqm3NBU_dn6XUdf69SQp8z-T55IqcA1&_nc_zt=23&_nc_ht=scontent.cdninstagram.com&edm=ANQ71j8EAAAA&_nc_gid=6zF1FeT4mOtd7D9M4acWzQ&_nc_tpa=Q5bMBQFJYeYe5YUHF-FncYjnzEpzJTheHmoL-2pSw_HC84XlYIo95YvJ4UqQOK_iRLcCAdT4hwvMxU5Y7A&oh=00_Af3xIWfHQhnu5gVWWjdKwZpbyX8uYo7isef6bvvWBfdz5A&oe=69F515FA\"\n              style=\"display: none; width: 100%; height: 100%; object-fit: cover; cursor: pointer;\" autoplay loop\n              playsinline referrerpolicy=\"no-referrer\" onclick=\"this.muted = !this.muted\" title=\"Click to toggle sound\">\n            </video>\n          </div>\n\n          <!-- <div class=\"npx-token-form\">\n            <label>Instagram Access Token</label>\n            <input type=\"text\" id=\"npxIgToken\" placeholder=\"EAABs...\" />\n            <input type=\"text\" id=\"npxMediaId\" placeholder=\"Media ID or Reel URL\" style=\"margin-top:4px\" />\n            <button onclick=\"npxLoadReel()\">Load Reel</button>\n          </div> -->\n        </div>\n\n        <!-- VIDEO INFO SIDE -->\n        <div class=\"npx-info-section\">\n\n          <!-- SKELETON LOADER -->\n          <div class=\"npx-skeleton\" id=\"npxSkeleton\">\n            <div class=\"npx-skel-line\" style=\"width: 40%; height: 16px; margin-bottom: 20px;\"></div>\n            <div class=\"npx-skel-line\" style=\"width: 80%; height: 24px; margin-bottom: 8px;\"></div>\n            <div class=\"npx-skel-line\" style=\"width: 30%; height: 14px; margin-bottom: 20px;\"></div>\n            <div style=\"display: flex; gap: 8px; margin-bottom: 20px;\">\n              <div class=\"npx-skel-line\" style=\"flex: 1; height: 36px;\"></div>\n              <div class=\"npx-skel-line\" style=\"flex: 1; height: 36px;\"></div>\n              <div class=\"npx-skel-line\" style=\"flex: 1; height: 36px;\"></div>\n            </div>\n            <div class=\"npx-skel-line\" style=\"width: 100%; height: 60px; margin-bottom: 20px;\"></div>\n            <div class=\"npx-skel-line\" style=\"width: 50%; height: 16px; margin-bottom: 12px;\"></div>\n            <div style=\"display: flex; gap: 12px; overflow: hidden;\">\n              <div class=\"npx-skel-line\" style=\"min-width: 90px; height: 140px; border-radius: 8px;\"></div>\n              <div class=\"npx-skel-line\" style=\"min-width: 90px; height: 140px; border-radius: 8px;\"></div>\n              <div class=\"npx-skel-line\" style=\"min-width: 90px; height: 140px; border-radius: 8px;\"></div>\n            </div>\n          </div>\n\n          <!-- ACTUAL CONTENT -->\n          <div id=\"npxInfoContent\" style=\"display: none; flex-direction: column; gap: 14px; width: 100%;\">\n            <div class=\"npx-section-label\">\n              <svg viewBox=\"0 0 24 24\">\n                <path d=\"M13 2.003A10 10 0 1 0 22 12 10 10 0 0 0 13 2.003zm-1 14.5v-9l6 4.5z\" />\n              </svg>\n              Video Info\n            </div>\n\n            <div class=\"npx-video-meta\" id=\"npxVideoMeta\">\n              <h3>Call Sirf 11.00 Baje Se Shaam 6.00 Baje Tak hi kare</h3>\n              <span class=\"npx-handle\">@avisaexperts</span>\n            </div>\n\n            <div class=\"npx-stat-row\">\n              <div class=\"npx-stat-chip\"><span class=\"npx-val\" id=\"npxStatViews\">12K</span><span\n                  class=\"npx-lbl\">Views</span></div>\n              <div class=\"npx-stat-chip\"><span class=\"npx-val\" id=\"npxStatLikes\">850</span><span\n                  class=\"npx-lbl\">Likes</span></div>\n              <div class=\"npx-stat-chip\"><span class=\"npx-val\" id=\"npxStatComments\">124</span><span\n                  class=\"npx-lbl\">Comments</span></div>\n            </div>\n\n            <div class=\"npx-caption-box\">\n              <p id=\"npxCaptionText\">Call Sirf 11.00 Baje Se Shaam 6.00 Baje Tak hi kare</p>\n              <div class=\"npx-hashtags\">\n                <span class=\"npx-hashtag\">#viralvideos</span>\n                <span class=\"npx-hashtag\">#visa</span>\n                <span class=\"npx-hashtag\">#famous</span>\n                <span class=\"npx-hashtag\">#avisaexperts</span>\n                <span class=\"npx-hashtag\">#kaveeshkapoor</span>\n              </div>\n            </div>\n\n            <div>\n              <p class=\"npx-related-title\">More from this creator</p>\n              <div class=\"npx-related-list\">\n                <!-- Hardcoded reels will be replaced by JS -->\n              </div>\n            </div>\n          </div>\n        </div>\n\n      </div>\n\n      <!-- RIGHT: BOOK APPOINTMENT -->\n      <div class=\"npx-right-panel\">\n\n        <div class=\"npx-appt-top\">\n          <div class=\"npx-appt-icon\">\n            <svg viewBox=\"0 0 24 24\">\n              <path\n                d=\"M19 4h-1V2h-2v2H8V2H6v2H5c-1.11 0-2 .89-2 2v14c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2V6c0-1.11-.9-2-2-2zm0 16H5V10h14v10zm0-12H5V6h14v2zM7 12h5v5H7z\" />\n            </svg>\n          </div>\n          <div>\n            <p class=\"npx-appt-title\">Book a<br />Consultation</p>\n            <p class=\"npx-appt-sub\">Talk to an expert.<br />Free 30-min session.</p>\n          </div>\n        </div>\n\n        <div class=\"npx-appt-features\">\n          <div class=\"npx-appt-feat\"><span class=\"npx-feat-dot\"></span>Choose your preferred time</div>\n          <div class=\"npx-appt-feat\"><span class=\"npx-feat-dot\"></span>Video or in-person meeting</div>\n          <div class=\"npx-appt-feat\"><span class=\"npx-feat-dot\"></span>Instant confirmation</div>\n          <div class=\"npx-appt-feat\"><span class=\"npx-feat-dot\"></span>No payment required</div>\n        </div>\n\n        <div class=\"npx-slots-preview\">\n          <p class=\"npx-slots-label\">Available Today</p>\n          <div class=\"npx-slot-pills\">\n            <span class=\"npx-slot-pill npx-avail\" onclick=\"npxSelectSlot(this)\">10:00 AM</span>\n            <span class=\"npx-slot-pill\" title=\"Not available\">11:30 AM</span>\n            <span class=\"npx-slot-pill npx-avail\" onclick=\"npxSelectSlot(this)\">2:00 PM</span>\n            <span class=\"npx-slot-pill npx-avail\" onclick=\"npxSelectSlot(this)\">4:30 PM</span>\n            <span class=\"npx-slot-pill\" title=\"Not available\">6:00 PM</span>\n          </div>\n        </div>\n\n        <div style=\"width:100%;display:flex;flex-direction:column;gap:8px\">\n          <button class=\"npx-appt-btn\" onclick=\"npxOpenLink(\'https://yoursite.com/book-appointment\')\">\n            <svg viewBox=\"0 0 24 24\">\n              <path\n                d=\"M19 4h-1V2h-2v2H8V2H6v2H5c-1.11 0-2 .89-2 2v14c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2V6c0-1.11-.9-2-2-2zm0 16H5V10h14v10z\" />\n            </svg>\n            Book Appointment\n          </button>\n          <p class=\"npx-appt-note\">Opens full booking page in a new tab</p>\n        </div>\n\n      </div>\n\n    </div>\n  </div>\n</div>\n\n<script>\n  // ==========================================\n  // DYNAMIC INSTAGRAM FETCHING LOGIC\n  // ==========================================\n  const IG_CONFIG = {\n    // ⚠️ Replace this with your actual Instagram Access Token\n    accessToken: \'\',\n    limit: 5 // How many posts to fetch\n  };\n\n  function showInfoContent() {\n    // Right panel\n    const skel = document.getElementById(\'npxSkeleton\');\n    const cont = document.getElementById(\'npxInfoContent\');\n    if (skel) skel.style.display = \'none\';\n    if (cont) cont.style.display = \'flex\';\n\n    // Left panel video\n    const vidSkel = document.getElementById(\'npxVideoSkeleton\');\n    const mainVid = document.getElementById(\'npxMainVideo\');\n    if (vidSkel) vidSkel.style.display = \'none\';\n    if (mainVid) mainVid.style.display = \'block\';\n  }\n\n  async function fetchLatestReels() {\n    if (!IG_CONFIG.accessToken || IG_CONFIG.accessToken === \'YOUR_INSTAGRAM_ACCESS_TOKEN\') {\n      console.warn(\'Instagram Access Token missing. Using hardcoded static reels as fallback.\');\n      showInfoContent();\n      return;\n    }\n\n    try {\n      // Fetch media from Instagram Graph API\n      const response = await fetch(`https://graph.instagram.com/me/media?fields=id,caption,media_type,media_url,thumbnail_url,timestamp&limit=${IG_CONFIG.limit}&access_token=${IG_CONFIG.accessToken}`);\n      const data = await response.json();\n\n      if (data.error) {\n        console.error(\'Error fetching Instagram data:\', data.error.message);\n        showInfoContent();\n        return;\n      }\n\n      // Filter only videos (reels)\n      const reels = data.data.filter(item => item.media_type === \'VIDEO\');\n\n      if (reels.length > 0) {\n        populateReelsUI(reels);\n        showInfoContent();\n      } else {\n        showInfoContent();\n      }\n    } catch (error) {\n      console.error(\'Network error fetching reels:\', error);\n      showInfoContent();\n    }\n  }\n\n  function populateReelsUI(reels) {\n    const listContainer = document.querySelector(\'.npx-related-list\');\n    listContainer.innerHTML = \'\'; // Clear hardcoded reels\n\n    reels.forEach((reel, index) => {\n      // Create thumbnail HTML\n      const thumbUrl = reel.thumbnail_url || \'\';\n      let title = (reel.caption || \'\').replace(/#\\w+/g, \'\').trim();\n      if (title.length > 20) title = title.substring(0, 20) + \'...\';\n      if (!title) title = \'Instagram Reel\';\n\n      const itemHtml = `\n        <div class=\"npx-related-item\"\n          data-media=\"${reel.media_url}\"\n          data-poster=\"${thumbUrl}\"\n          data-caption=\"${(reel.caption || \'\').replace(/\"/g, \'&quot;\')}\"\n          onclick=\"npxChangeReel(this)\">\n          <div class=\"npx-related-thumb\" style=\"padding:0; overflow:hidden;\">\n            ${thumbUrl ? `<img src=\"${thumbUrl}\" style=\"width:100%;height:100%;object-fit:cover;\" referrerpolicy=\"no-referrer\" />` : \'\'}\n          </div>\n          <div class=\"npx-related-info\" style=\"min-width:0;\">\n            <p style=\"white-space:nowrap;overflow:hidden;text-overflow:ellipsis;\">${title}</p>\n            <span>Play Reel</span>\n          </div>\n        </div>\n      `;\n      listContainer.innerHTML += itemHtml;\n\n      // Automatically load the first reel into the main viewer\n      if (index === 0) {\n        // Find the newly added element and trigger click\n        const firstReelEl = listContainer.querySelector(\'.npx-related-item\');\n        if (firstReelEl) npxChangeReel(firstReelEl);\n      }\n    });\n  }\n\n  // Fetch reels when page loads\n  document.addEventListener(\'DOMContentLoaded\', fetchLatestReels);\n\n  // ==========================================\n  // EXISTING FUNCTIONS\n  // ==========================================\n  function npxLoadReel() {\n    const token = document.getElementById(\'npxIgToken\').value.trim();\n    const mediaId = document.getElementById(\'npxMediaId\').value.trim();\n    const frame = document.getElementById(\'npxReelFrame\');\n    const placeholder = document.getElementById(\'npxReelPlaceholder\');\n\n    if (!token || !mediaId) {\n      placeholder.querySelector(\'span\').textContent = \'Please enter both token and media ID.\';\n      return;\n    }\n\n    placeholder.querySelector(\'span\').textContent = \'Loading reel...\';\n\n    const existing = frame.querySelector(\'iframe\');\n    if (existing) existing.remove();\n\n    const url = `https://www.instagram.com/p/${mediaId}/embed/`;\n    const iframe = document.createElement(\'iframe\');\n    iframe.src = url;\n    iframe.style.cssText = \'width:100%;height:100%;border:none;border-radius:14px;\';\n    iframe.allow = \'autoplay; encrypted-media\';\n    iframe.onload = () => { placeholder.style.display = \'none\'; };\n    iframe.onerror = () => { placeholder.querySelector(\'span\').textContent = \'Could not load reel. Check your media ID.\'; };\n    frame.insertBefore(iframe, frame.querySelector(\'.npx-play-btn\'));\n  }\n\n  function npxOpenLink(url) {\n    window.open(url, \'_blank\');\n  }\n\n  function npxSelectSlot(element) {\n    document.querySelectorAll(\'.npx-slot-pill.npx-avail\').forEach(el => {\n      el.classList.remove(\'npx-selected\');\n    });\n    element.classList.add(\'npx-selected\');\n\n    const btn = document.querySelector(\'.npx-appt-btn\');\n    btn.innerHTML = \'<svg viewBox=\"0 0 24 24\"><path d=\"M19 4h-1V2h-2v2H8V2H6v2H5c-1.11 0-2 .89-2 2v14c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2V6c0-1.11-.9-2-2-2zm0 16H5V10h14v10z\"/></svg> Book for \' + element.innerText;\n  }\n\n  function npxChangeReel(element) {\n    const media = element.getAttribute(\'data-media\');\n    const poster = element.getAttribute(\'data-poster\');\n    const captionRaw = element.getAttribute(\'data-caption\') || \'Instagram Reel\';\n\n    // Update video source\n    const video = document.querySelector(\'#npxReelFrame video\');\n    video.src = media;\n    video.poster = poster;\n    video.load();\n\n    // 1. Try to play with sound ON by default\n    video.muted = false;\n\n    video.play().catch(e => {\n      console.log(\'Browser blocked autoplay with sound. Falling back to muted autoplay.\');\n      // 2. If the browser blocks it (because the user hasn\'t clicked anything yet), \n      //    fallback to playing it muted so the video at least plays.\n      video.muted = true;\n      video.play().catch(err => console.log(\'Autoplay completely blocked:\', err));\n    });\n\n    // Parse caption and hashtags\n    let title = captionRaw.replace(/#\\w+/g, \'\').trim();\n    if (title.length > 65) title = title.substring(0, 65) + \'...\';\n    if (title.length === 0) title = \'Instagram Reel\';\n\n    document.querySelector(\'#npxVideoMeta h3\').innerText = title;\n    document.getElementById(\'npxCaptionText\').innerText = captionRaw.replace(/#\\w+/g, \'\').trim();\n\n    // Extract hashtags and update UI\n    const hashtags = captionRaw.match(/#\\w+/g) || [];\n    const tagsHtml = hashtags.map(t => `<span class=\"npx-hashtag\">${t}</span>`).join(\'\');\n    document.querySelector(\'.npx-hashtags\').innerHTML = tagsHtml;\n\n    // Randomize stats slightly to feel dynamic\n    document.getElementById(\'npxStatViews\').innerText = Math.floor(Math.random() * 50 + 5) + \'K\';\n    document.getElementById(\'npxStatLikes\').innerText = Math.floor(Math.random() * 900 + 100);\n    document.getElementById(\'npxStatComments\').innerText = Math.floor(Math.random() * 150 + 10);\n  }\n</script>', '2026-05-21 07:22:06');
INSERT INTO `banner_code_snapshot` (`id`, `code_content`, `created_at`) VALUES
(76, '<style>\n  @import url(\'https://fonts.googleapis.com/css2?family=Playfair+Display:wght@600;700&family=DM+Sans:wght@300;400;500&display=swap\');\n\n  :root {\n    --npx-c1: #0f0f0f;\n    --npx-c2: #1a1a2e;\n    --npx-c3: #16213e;\n    --npx-c4: #0f3460;\n    --npx-acc: #e94560;\n    --npx-acc2: #f5a623;\n    --npx-light: #f8f4ef;\n    --npx-muted: #a0a0b0;\n  }\n\n  .npx-popup-backdrop,\n  .npx-popup-backdrop * {\n    box-sizing: border-box;\n    margin: 0;\n    padding: 0;\n  }\n\n  .npx-popup-backdrop {\n    font-family: \'DM Sans\', sans-serif;\n    /* position: fixed; */\n    top: 0;\n    left: 0;\n    /* width: 100vw;\n    height: 100vh; */\n    background: rgba(0, 0, 0, 0.75);\n    backdrop-filter: blur(8px);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    z-index: 9999;\n    /* padding: 20px; */\n  }\n\n  .npx-popup-overlay {\n    background: rgba(10, 10, 20, 0.92);\n    border-radius: 20px;\n    overflow: hidden;\n    display: flex;\n    flex-direction: column;\n    min-height: 580px;\n    width: 100%;\n    max-width: 900px;\n    border: 1px solid rgba(255, 255, 255, 0.08);\n    position: relative;\n    box-shadow: 0 30px 60px rgba(0, 0, 0, 0.5);\n    animation: npxPopIn 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;\n  }\n\n  @keyframes npxPopIn {\n    0% {\n      opacity: 0;\n      transform: scale(0.9) translateY(20px);\n    }\n\n    100% {\n      opacity: 1;\n      transform: scale(1) translateY(0);\n    }\n  }\n\n  .npx-skeleton {\n    display: flex;\n    flex-direction: column;\n    width: 100%;\n    gap: 12px;\n    animation: npxPulse 1.5s infinite ease-in-out;\n  }\n\n  .npx-skel-line {\n    background: rgba(255, 255, 255, 0.08);\n    border-radius: 6px;\n  }\n\n  @keyframes npxPulse {\n    0% {\n      opacity: 0.5;\n    }\n\n    50% {\n      opacity: 1;\n    }\n\n    100% {\n      opacity: 0.5;\n    }\n  }\n\n  .npx-popup-header {\n    background: linear-gradient(90deg, #0f3460, #16213e);\n    padding: 14px 22px;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    border-bottom: 1px solid rgba(255, 255, 255, 0.07);\n  }\n\n  .npx-popup-header h2 {\n    font-family: \'Playfair Display\', serif;\n    font-size: 17px;\n    color: #fff;\n    letter-spacing: 0.3px;\n  }\n\n  .npx-live-badge {\n    background: var(--npx-acc);\n    color: #fff;\n    font-size: 10px;\n    font-weight: 500;\n    padding: 3px 10px;\n    border-radius: 20px;\n    display: flex;\n    align-items: center;\n    gap: 5px;\n    letter-spacing: 0.5px;\n  }\n\n  .npx-live-dot {\n    width: 6px;\n    height: 6px;\n    border-radius: 50%;\n    background: #fff;\n    animation: npxBlink 1.2s infinite;\n  }\n\n  @keyframes npxBlink {\n\n    0%,\n    100% {\n      opacity: 1;\n    }\n\n    50% {\n      opacity: 0.2;\n    }\n  }\n\n  .npx-popup-close {\n    width: 28px;\n    height: 28px;\n    border-radius: 50%;\n    border: 1px solid rgba(255, 255, 255, 0.15);\n    background: rgba(255, 255, 255, 0.06);\n    color: #ccc;\n    font-size: 16px;\n    cursor: pointer;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    line-height: 1;\n  }\n\n  .npx-popup-body {\n    display: grid;\n    grid-template-columns: minmax(0, 2fr) minmax(260px, 1fr);\n    flex: 1;\n    min-height: 0;\n  }\n\n  .npx-left-panel {\n    display: grid;\n    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);\n    border-right: 1px solid rgba(255, 255, 255, 0.07);\n    min-width: 0;\n  }\n\n  .npx-reel-section {\n    background: #0a0a14;\n    padding: 18px 16px;\n    border-right: 1px solid rgba(255, 255, 255, 0.06);\n    display: flex;\n    flex-direction: column;\n    gap: 12px;\n  }\n\n  .npx-section-label {\n    font-size: 10px;\n    text-transform: uppercase;\n    letter-spacing: 1.5px;\n    color: var(--npx-muted);\n    display: flex;\n    align-items: center;\n    gap: 6px;\n  }\n\n  .npx-section-label svg {\n    width: 12px;\n    height: 12px;\n    fill: var(--npx-acc);\n  }\n\n  .npx-reel-frame {\n    background: #111;\n    border-radius: 14px;\n    overflow: hidden;\n    position: relative;\n    aspect-ratio: 9/14;\n    border: 1px solid rgba(255, 255, 255, 0.08);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    cursor: pointer;\n  }\n\n  .npx-reel-placeholder {\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 10px;\n    color: rgba(255, 255, 255, 0.3);\n  }\n\n  .npx-reel-placeholder svg {\n    width: 36px;\n    height: 36px;\n    opacity: 0.4;\n  }\n\n  .npx-reel-placeholder span {\n    font-size: 11px;\n    text-align: center;\n    max-width: 110px;\n    line-height: 1.5;\n  }\n\n  .npx-reel-frame .npx-play-btn {\n    width: 48px;\n    height: 48px;\n    border-radius: 50%;\n    background: rgba(233, 69, 96, 0.85);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    position: absolute;\n    bottom: 14px;\n    right: 14px;\n    cursor: pointer;\n    transition: transform 0.15s;\n  }\n\n  .npx-reel-frame .npx-play-btn:hover {\n    transform: scale(1.1);\n  }\n\n  .npx-play-btn svg {\n    width: 18px;\n    height: 18px;\n    fill: #fff;\n    margin-left: 2px;\n  }\n\n  .npx-token-form {\n    display: flex;\n    flex-direction: column;\n    gap: 6px;\n  }\n\n  .npx-token-form label {\n    font-size: 10px;\n    color: var(--npx-muted);\n    letter-spacing: 0.5px;\n  }\n\n  .npx-token-form input {\n    background: rgba(255, 255, 255, 0.05);\n    border: 1px solid rgba(255, 255, 255, 0.1);\n    border-radius: 8px;\n    color: #fff;\n    font-size: 11px;\n    padding: 7px 10px;\n    font-family: monospace;\n    outline: none;\n    width: 100%;\n    transition: border-color 0.2s;\n  }\n\n  .npx-token-form input:focus {\n    border-color: var(--npx-acc);\n  }\n\n  .npx-token-form button {\n    background: var(--npx-acc);\n    color: #fff;\n    border: none;\n    border-radius: 8px;\n    padding: 7px;\n    font-size: 11px;\n    font-family: \'DM Sans\', sans-serif;\n    cursor: pointer;\n    font-weight: 500;\n    transition: opacity 0.2s;\n    margin-top: 2px;\n  }\n\n  .npx-token-form button:hover {\n    opacity: 0.85;\n  }\n\n  .npx-info-section {\n    background: #0d0d1a;\n    padding: 18px 16px;\n    display: flex;\n    flex-direction: column;\n    gap: 14px;\n    overflow-y: auto;\n    overflow-x: hidden;\n    max-height: 100%;\n  }\n\n  .npx-info-section::-webkit-scrollbar {\n    width: 4px;\n  }\n\n  .npx-info-section::-webkit-scrollbar-track {\n    background: transparent;\n  }\n\n  .npx-info-section::-webkit-scrollbar-thumb {\n    background: rgba(255, 255, 255, 0.1);\n    border-radius: 4px;\n  }\n\n  .npx-video-meta {\n    display: flex;\n    flex-direction: column;\n    gap: 4px;\n  }\n\n  .npx-video-meta h3 {\n    font-family: \'Playfair Display\', serif;\n    font-size: 14px;\n    color: #fff;\n    line-height: 1.4;\n  }\n\n  .npx-video-meta .npx-handle {\n    font-size: 11px;\n    color: var(--npx-acc2);\n  }\n\n  .npx-stat-row {\n    display: flex;\n    gap: 8px;\n    flex-wrap: wrap;\n  }\n\n  .npx-stat-chip {\n    background: rgba(255, 255, 255, 0.05);\n    border: 1px solid rgba(255, 255, 255, 0.08);\n    border-radius: 8px;\n    padding: 6px 10px;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 1px;\n    flex: 1;\n    min-width: 52px;\n  }\n\n  .npx-stat-chip .npx-val {\n    font-size: 13px;\n    font-weight: 500;\n    color: #fff;\n  }\n\n  .npx-stat-chip .npx-lbl {\n    font-size: 9px;\n    color: var(--npx-muted);\n    text-transform: uppercase;\n    letter-spacing: 0.8px;\n  }\n\n  .npx-caption-box {\n    background: rgba(255, 255, 255, 0.03);\n    border: 1px solid rgba(255, 255, 255, 0.06);\n    border-radius: 10px;\n    padding: 10px;\n  }\n\n  .npx-caption-box p {\n    font-size: 11px;\n    color: rgba(255, 255, 255, 0.55);\n    line-height: 1.7;\n  }\n\n  .npx-caption-box .npx-hashtags {\n    margin-top: 6px;\n    display: flex;\n    flex-wrap: wrap;\n    gap: 4px;\n  }\n\n  .npx-hashtag {\n    font-size: 10px;\n    color: var(--npx-acc2);\n    background: rgba(245, 166, 35, 0.08);\n    border: 1px solid rgba(245, 166, 35, 0.15);\n    border-radius: 6px;\n    padding: 2px 7px;\n  }\n\n  .npx-related-title {\n    font-size: 10px;\n    text-transform: uppercase;\n    letter-spacing: 1px;\n    color: var(--npx-muted);\n  }\n\n  .npx-related-list {\n    display: flex;\n    flex-direction: row;\n    gap: 12px;\n    overflow-x: auto;\n    scroll-behavior: smooth;\n    scroll-snap-type: x mandatory;\n    padding-bottom: 8px;\n  }\n\n  .npx-related-list::-webkit-scrollbar {\n    height: 4px;\n  }\n\n  .npx-related-list::-webkit-scrollbar-track {\n    background: rgba(255, 255, 255, 0.05);\n    border-radius: 4px;\n  }\n\n  .npx-related-list::-webkit-scrollbar-thumb {\n    background: rgba(255, 255, 255, 0.2);\n    border-radius: 4px;\n  }\n\n  .npx-related-item {\n    display: flex;\n    flex-direction: column;\n    gap: 6px;\n    align-items: stretch;\n    padding: 6px;\n    border-radius: 8px;\n    background: rgba(255, 255, 255, 0.03);\n    border: 1px solid rgba(255, 255, 255, 0.05);\n    cursor: pointer;\n    transition: background 0.15s, transform 0.15s;\n    flex: 0 0 90px;\n    scroll-snap-align: start;\n  }\n\n  .npx-related-item:hover {\n    background: rgba(255, 255, 255, 0.07);\n    transform: translateY(-2px);\n  }\n\n  .npx-related-thumb {\n    width: 100%;\n    height: 138px;\n    border-radius: 4px;\n    background: linear-gradient(135deg, #1a1a3e, #0f3460);\n    flex-shrink: 0;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    overflow: hidden;\n  }\n\n  .npx-related-thumb svg {\n    width: 14px;\n    height: 14px;\n    fill: rgba(255, 255, 255, 0.4);\n  }\n\n  .npx-related-info p {\n    font-size: 10px;\n    color: rgba(255, 255, 255, 0.7);\n    line-height: 1.3;\n    white-space: nowrap;\n    overflow: hidden;\n    text-overflow: ellipsis;\n  }\n\n  .npx-related-info span {\n    font-size: 10px;\n    color: var(--npx-muted);\n  }\n\n  .npx-right-panel {\n    background: linear-gradient(160deg, #0a0a18 0%, #0f1a35 50%, #0a0a18 100%);\n    padding: 30px 20px;\n    display: block;\n    text-align: center;\n    min-width: 250px;\n    position: relative;\n  }\n\n  .npx-right-panel::before {\n    content: \'\';\n    position: absolute;\n    top: -60px;\n    left: 50%;\n    transform: translateX(-50%);\n    width: 180px;\n    height: 180px;\n    border-radius: 50%;\n    background: radial-gradient(circle, rgba(233, 69, 96, 0.12), transparent 70%);\n    pointer-events: none;\n  }\n\n  .npx-appt-top {\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 12px;\n    padding-top: 8px;\n    margin-bottom: 24px;\n  }\n\n  .npx-appt-icon {\n    width: 52px;\n    height: 52px;\n    border-radius: 16px;\n    background: rgba(233, 69, 96, 0.12);\n    border: 1px solid rgba(233, 69, 96, 0.25);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n\n  .npx-appt-icon svg {\n    width: 26px;\n    height: 26px;\n    fill: var(--npx-acc);\n  }\n\n  .npx-appt-title {\n    font-family: \'Playfair Display\', serif;\n    font-size: 15px;\n    color: #fff;\n    line-height: 1.4;\n  }\n\n  .npx-appt-sub {\n    font-size: 11px;\n    color: var(--npx-muted);\n    line-height: 1.6;\n  }\n\n  .npx-appt-features {\n    display: flex;\n    flex-direction: column;\n    gap: 7px;\n    width: 100%;\n    margin-bottom: 24px;\n  }\n\n  .npx-appt-feat {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    font-size: 11px;\n    color: rgba(255, 255, 255, 0.6);\n  }\n\n  .npx-feat-dot {\n    width: 5px;\n    height: 5px;\n    border-radius: 50%;\n    background: var(--npx-acc2);\n    flex-shrink: 0;\n  }\n\n  .npx-slots-preview {\n    width: 100%;\n    background: rgba(255, 255, 255, 0.03);\n    border: 1px solid rgba(255, 255, 255, 0.07);\n    border-radius: 10px;\n    padding: 10px;\n    margin-bottom: 24px;\n  }\n\n  .npx-slots-label {\n    font-size: 9px;\n    color: var(--npx-muted);\n    text-transform: uppercase;\n    letter-spacing: 1px;\n    margin-bottom: 6px;\n  }\n\n  .npx-slot-pills {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 4px;\n  }\n\n  .npx-slot-pill {\n    font-size: 10px;\n    padding: 3px 8px;\n    border-radius: 6px;\n    border: 1px solid rgba(255, 255, 255, 0.1);\n    color: rgba(255, 255, 255, 0.5);\n    transition: all 0.2s ease;\n  }\n\n  .npx-slot-pill.npx-avail {\n    border-color: rgba(15, 180, 100, 0.3);\n    color: rgba(15, 200, 120, 0.8);\n    background: rgba(15, 180, 100, 0.07);\n    cursor: pointer;\n  }\n\n  .npx-slot-pill.npx-avail:hover {\n    background: rgba(15, 180, 100, 0.15);\n    border-color: rgba(15, 180, 100, 0.5);\n    transform: translateY(-1px);\n  }\n\n  .npx-slot-pill.npx-avail.npx-selected {\n    background: var(--npx-acc);\n    border-color: var(--npx-acc);\n    color: #fff;\n    box-shadow: 0 4px 10px rgba(233, 69, 96, 0.3);\n  }\n\n  .npx-appt-btn {\n    width: 100%;\n    background: var(--npx-acc);\n    color: #fff;\n    border: none;\n    border-radius: 12px;\n    padding: 13px;\n    font-size: 13px;\n    font-weight: 500;\n    font-family: \'DM Sans\', sans-serif;\n    cursor: pointer;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    gap: 7px;\n    transition: transform 0.15s, opacity 0.15s;\n    letter-spacing: 0.2px;\n  }\n\n  .npx-appt-btn:hover {\n    opacity: 0.9;\n    transform: translateY(-1px);\n  }\n\n  .npx-appt-btn:active {\n    transform: scale(0.98);\n  }\n\n  .npx-appt-btn svg {\n    width: 16px;\n    height: 16px;\n    fill: #fff;\n  }\n\n  .npx-appt-note {\n    font-size: 10px;\n    color: rgba(255, 255, 255, 0.25);\n    line-height: 1.5;\n  }\n\n  @media (max-width: 850px) {\n    .npx-popup-body {\n      grid-template-columns: 1fr;\n    }\n\n    .npx-left-panel {\n      grid-template-columns: 1fr;\n      border-right: none;\n      border-bottom: 1px solid rgba(255, 255, 255, 0.07);\n    }\n\n    .npx-popup-overlay {\n      height: 90vh;\n      overflow-y: auto;\n      max-width: 95vw;\n    }\n\n    .npx-right-panel {\n      padding: 30px 16px;\n      gap: 20px;\n    }\n\n    .npx-reel-frame {\n      width: 100%;\n      height: 100%;\n    }\n  }\n</style>\n\n<h2 class=\"npx-sr-only\"\n  style=\"position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border-width:0;\">\n  Latest news popup with Instagram reel viewer and appointment booking</h2>\n\n<div class=\"npx-popup-backdrop\" id=\"npxPopupBackdrop\">\n  <div class=\"npx-popup-overlay\">\n\n    <div class=\"npx-popup-body\">\n\n      <div class=\"npx-left-panel\">\n\n        <!-- INSTAGRAM REEL SIDE -->\n        <div class=\"npx-reel-section\" style=\"justify-content: center; padding: 0;\">\n          <div class=\"npx-reel-frame\" id=\"npxReelFrame\"\n            style=\"height: 100%; border-radius: 0; border-right: 1px solid rgba(255, 255, 255, 0.08); overflow: hidden;\">\n\n            <!-- VIDEO SKELETON LOADER -->\n            <div id=\"npxVideoSkeleton\"\n              style=\"width: 100%; height: 100%; background: rgba(255, 255, 255, 0.05); animation: npxPulse 1.5s infinite ease-in-out;\">\n            </div>\n\n            <video id=\"npxMainVideo\"\n              src=\"https://instagram.fdel1-7.fna.fbcdn.net/o1/v/t2/f2/m86/AQO5sIiKbPw1xkABk9k7Sl_Og_DC_-z2-XmV5EQV3OgwjGuIKWMDSfwNTegQ460MWu4uT421GlSfFsw3STzmfFxVlb8wmNWzjzQZtsk.mp4?_nc_cat=103&_nc_oc=AdpOCAB9FAiyBIZdm03WcZKCyDNMZimduxyi3ul9tcJ_69injBOV6gd5WZNfL-cUH1PD8tkVo4gjACEu9bfhaxbE&_nc_sid=5e9851&_nc_ht=instagram.fdel1-7.fna.fbcdn.net&_nc_ohc=2kLsowPX0VIQ7kNvwGI-9AF&efg=eyJ2ZW5jb2RlX3RhZyI6Inhwdl9wcm9ncmVzc2l2ZS5JTlNUQUdSQU0uQ0xJUFMuQzMuNzIwLmRhc2hfYmFzZWxpbmVfMV92MSIsInhwdl9hc3NldF9pZCI6MTc5MTM3NTM1MTMzNjQ3NDMsImFzc2V0X2FnZV9kYXlzIjozLCJ2aV91c2VjYXNlX2lkIjoxMDA5OSwiZHVyYXRpb25fcyI6ODksInVybGdlbl9zb3VyY2UiOiJ3d3cifQ%3D%3D&ccb=17-1&vs=35508edcd865211d&_nc_&_nc_gid=6zF1FeT4mOtd7D9M4acWzQ&edm=ANQ71j8EAAAA&_nc_zt=28&_nc_tpa=Q5bMBQFJGIg9ypkpDPIyibfpxGJZt8I1UOMdB18a0nq1rOQFPJC6F7KDgXEcl-GwAw5Ch2jFKjcF6JrlzA&oh=00_Af3iKm-2V2vnHbFsJZ-giGoqYRj24U_N5c59J6pGZhMytQ&oe=69F10D18\"\n              poster=\"https://scontent.cdninstagram.com/v/t51.82787-15/672336940_17913753534364743_7989516135913121464_n.jpg?stp=dst-jpg_e35_tt6&_nc_cat=102&ccb=7-5&_nc_sid=18de74&efg=eyJlZmdfdGFnIjoiQ0xJUFMuYmVzdF9pbWFnZV91cmxnZW4uQzMifQ%3D%3D&_nc_ohc=1zhwq2Ng-t4Q7kNvwGoLkpr&_nc_oc=AdqSGR7_l5tiEmor48v7M2-AxPD3H2aoaZ-WWkrbEq1zXTWvnfBLU6wkpYqm3NBU_dn6XUdf69SQp8z-T55IqcA1&_nc_zt=23&_nc_ht=scontent.cdninstagram.com&edm=ANQ71j8EAAAA&_nc_gid=6zF1FeT4mOtd7D9M4acWzQ&_nc_tpa=Q5bMBQFJYeYe5YUHF-FncYjnzEpzJTheHmoL-2pSw_HC84XlYIo95YvJ4UqQOK_iRLcCAdT4hwvMxU5Y7A&oh=00_Af3xIWfHQhnu5gVWWjdKwZpbyX8uYo7isef6bvvWBfdz5A&oe=69F515FA\"\n              style=\"display: none; width: 100%; height: 100%; object-fit: cover; cursor: pointer;\" autoplay loop\n              playsinline referrerpolicy=\"no-referrer\" onclick=\"this.muted = !this.muted\" title=\"Click to toggle sound\">\n            </video>\n          </div>\n\n          <!-- <div class=\"npx-token-form\">\n            <label>Instagram Access Token</label>\n            <input type=\"text\" id=\"npxIgToken\" placeholder=\"EAABs...\" />\n            <input type=\"text\" id=\"npxMediaId\" placeholder=\"Media ID or Reel URL\" style=\"margin-top:4px\" />\n            <button onclick=\"npxLoadReel()\">Load Reel</button>\n          </div> -->\n        </div>\n\n        <!-- VIDEO INFO SIDE -->\n        <div class=\"npx-info-section\">\n\n          <!-- SKELETON LOADER -->\n          <div class=\"npx-skeleton\" id=\"npxSkeleton\">\n            <div class=\"npx-skel-line\" style=\"width: 40%; height: 16px; margin-bottom: 20px;\"></div>\n            <div class=\"npx-skel-line\" style=\"width: 80%; height: 24px; margin-bottom: 8px;\"></div>\n            <div class=\"npx-skel-line\" style=\"width: 30%; height: 14px; margin-bottom: 20px;\"></div>\n            <div style=\"display: flex; gap: 8px; margin-bottom: 20px;\">\n              <div class=\"npx-skel-line\" style=\"flex: 1; height: 36px;\"></div>\n              <div class=\"npx-skel-line\" style=\"flex: 1; height: 36px;\"></div>\n              <div class=\"npx-skel-line\" style=\"flex: 1; height: 36px;\"></div>\n            </div>\n            <div class=\"npx-skel-line\" style=\"width: 100%; height: 60px; margin-bottom: 20px;\"></div>\n            <div class=\"npx-skel-line\" style=\"width: 50%; height: 16px; margin-bottom: 12px;\"></div>\n            <div style=\"display: flex; gap: 12px; overflow: hidden;\">\n              <div class=\"npx-skel-line\" style=\"min-width: 90px; height: 140px; border-radius: 8px;\"></div>\n              <div class=\"npx-skel-line\" style=\"min-width: 90px; height: 140px; border-radius: 8px;\"></div>\n              <div class=\"npx-skel-line\" style=\"min-width: 90px; height: 140px; border-radius: 8px;\"></div>\n            </div>\n          </div>\n\n          <!-- ACTUAL CONTENT -->\n          <div id=\"npxInfoContent\" style=\"display: none; flex-direction: column; gap: 14px; width: 100%;\">\n            <div class=\"npx-section-label\">\n              <svg viewBox=\"0 0 24 24\">\n                <path d=\"M13 2.003A10 10 0 1 0 22 12 10 10 0 0 0 13 2.003zm-1 14.5v-9l6 4.5z\" />\n              </svg>\n              Video Info\n            </div>\n\n            <div class=\"npx-video-meta\" id=\"npxVideoMeta\">\n              <h3>Call Sirf 11.00 Baje Se Shaam 6.00 Baje Tak hi kare</h3>\n              <span class=\"npx-handle\">@avisaexperts</span>\n            </div>\n\n            <div class=\"npx-stat-row\">\n              <div class=\"npx-stat-chip\"><span class=\"npx-val\" id=\"npxStatViews\">12K</span><span\n                  class=\"npx-lbl\">Views</span></div>\n              <div class=\"npx-stat-chip\"><span class=\"npx-val\" id=\"npxStatLikes\">850</span><span\n                  class=\"npx-lbl\">Likes</span></div>\n              <div class=\"npx-stat-chip\"><span class=\"npx-val\" id=\"npxStatComments\">124</span><span\n                  class=\"npx-lbl\">Comments</span></div>\n            </div>\n\n            <div class=\"npx-caption-box\">\n              <p id=\"npxCaptionText\">Call Sirf 11.00 Baje Se Shaam 6.00 Baje Tak hi kare</p>\n              <div class=\"npx-hashtags\">\n                <span class=\"npx-hashtag\">#viralvideos</span>\n                <span class=\"npx-hashtag\">#visa</span>\n                <span class=\"npx-hashtag\">#famous</span>\n                <span class=\"npx-hashtag\">#avisaexperts</span>\n                <span class=\"npx-hashtag\">#kaveeshkapoor</span>\n              </div>\n            </div>\n\n            <div>\n              <p class=\"npx-related-title\">More from this creator</p>\n              <div class=\"npx-related-list\">\n                <!-- Hardcoded reels will be replaced by JS -->\n              </div>\n            </div>\n          </div>\n        </div>\n\n      </div>\n\n      <!-- RIGHT: BOOK APPOINTMENT -->\n      <div class=\"npx-right-panel\">\n\n        <div class=\"npx-appt-top\">\n          <div class=\"npx-appt-icon\">\n            <svg viewBox=\"0 0 24 24\">\n              <path\n                d=\"M19 4h-1V2h-2v2H8V2H6v2H5c-1.11 0-2 .89-2 2v14c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2V6c0-1.11-.9-2-2-2zm0 16H5V10h14v10zm0-12H5V6h14v2zM7 12h5v5H7z\" />\n            </svg>\n          </div>\n          <div>\n            <p class=\"npx-appt-title\">Book a<br />Consultation</p>\n            <p class=\"npx-appt-sub\">Talk to an expert.<br />Free 30-min session.</p>\n          </div>\n        </div>\n\n        <div class=\"npx-appt-features\">\n          <div class=\"npx-appt-feat\"><span class=\"npx-feat-dot\"></span>Choose your preferred time</div>\n          <div class=\"npx-appt-feat\"><span class=\"npx-feat-dot\"></span>Video or in-person meeting</div>\n          <div class=\"npx-appt-feat\"><span class=\"npx-feat-dot\"></span>Instant confirmation</div>\n          <div class=\"npx-appt-feat\"><span class=\"npx-feat-dot\"></span>No payment required</div>\n        </div>\n\n        <div class=\"npx-slots-preview\">\n          <p class=\"npx-slots-label\">Available Today</p>\n          <div class=\"npx-slot-pills\">\n            <span class=\"npx-slot-pill npx-avail\" onclick=\"npxSelectSlot(this)\">10:00 AM</span>\n            <span class=\"npx-slot-pill\" title=\"Not available\">11:30 AM</span>\n            <span class=\"npx-slot-pill npx-avail\" onclick=\"npxSelectSlot(this)\">2:00 PM</span>\n            <span class=\"npx-slot-pill npx-avail\" onclick=\"npxSelectSlot(this)\">4:30 PM</span>\n            <span class=\"npx-slot-pill\" title=\"Not available\">6:00 PM</span>\n          </div>\n        </div>\n\n        <div style=\"width:100%;display:flex;flex-direction:column;gap:8px\">\n          <button class=\"npx-appt-btn\" onclick=\"npxOpenLink(\'https://yoursite.com/book-appointment\')\">\n            <svg viewBox=\"0 0 24 24\">\n              <path\n                d=\"M19 4h-1V2h-2v2H8V2H6v2H5c-1.11 0-2 .89-2 2v14c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2V6c0-1.11-.9-2-2-2zm0 16H5V10h14v10z\" />\n            </svg>\n            Book Appointment\n          </button>\n          <p class=\"npx-appt-note\">Opens full booking page in a new tab</p>\n        </div>\n\n      </div>\n\n    </div>\n  </div>\n</div>\n\n<script>\n  // ==========================================\n  // DYNAMIC INSTAGRAM FETCHING LOGIC\n  // ==========================================\n  const IG_CONFIG = {\n    // ⚠️ Replace this with your actual Instagram Access Token\n    accessToken: \'IGAAWp7Lk0ae5BZAFpGMzlFQ21LMWdXYXFUYzBKU3c0WWFuc0k4ZAWl6eU5Hal9NVWE5LWVVc2lUNm9FNUxncVVIYlk0ZAkJBWHdhMDB1X2MwT0UtQVV4QmdJMW1qeGZAwb2lFMVBrUXdmWkdmelliTE9ISTd1QlI0VmdiMlJzSFU3NAZDZD\',\n    limit: 5 // How many posts to fetch\n  };\n\n  function showInfoContent() {\n    // Right panel\n    const skel = document.getElementById(\'npxSkeleton\');\n    const cont = document.getElementById(\'npxInfoContent\');\n    if (skel) skel.style.display = \'none\';\n    if (cont) cont.style.display = \'flex\';\n\n    // Left panel video\n    const vidSkel = document.getElementById(\'npxVideoSkeleton\');\n    const mainVid = document.getElementById(\'npxMainVideo\');\n    if (vidSkel) vidSkel.style.display = \'none\';\n    if (mainVid) mainVid.style.display = \'block\';\n  }\n\n  async function fetchLatestReels() {\n    if (!IG_CONFIG.accessToken || IG_CONFIG.accessToken === \'YOUR_INSTAGRAM_ACCESS_TOKEN\') {\n      console.warn(\'Instagram Access Token missing. Using hardcoded static reels as fallback.\');\n      showInfoContent();\n      return;\n    }\n\n    try {\n      // Fetch media from Instagram Graph API\n      const response = await fetch(`https://graph.instagram.com/me/media?fields=id,caption,media_type,media_url,thumbnail_url,timestamp&limit=${IG_CONFIG.limit}&access_token=${IG_CONFIG.accessToken}`);\n      const data = await response.json();\n\n      if (data.error) {\n        console.error(\'Error fetching Instagram data:\', data.error.message);\n        showInfoContent();\n        return;\n      }\n\n      // Filter only videos (reels)\n      const reels = data.data.filter(item => item.media_type === \'VIDEO\');\n\n      if (reels.length > 0) {\n        populateReelsUI(reels);\n        showInfoContent();\n      } else {\n        showInfoContent();\n      }\n    } catch (error) {\n      console.error(\'Network error fetching reels:\', error);\n      showInfoContent();\n    }\n  }\n\n  function populateReelsUI(reels) {\n    const listContainer = document.querySelector(\'.npx-related-list\');\n    listContainer.innerHTML = \'\'; // Clear hardcoded reels\n\n    reels.forEach((reel, index) => {\n      // Create thumbnail HTML\n      const thumbUrl = reel.thumbnail_url || \'\';\n      let title = (reel.caption || \'\').replace(/#\\w+/g, \'\').trim();\n      if (title.length > 20) title = title.substring(0, 20) + \'...\';\n      if (!title) title = \'Instagram Reel\';\n\n      const itemHtml = `\n        <div class=\"npx-related-item\"\n          data-media=\"${reel.media_url}\"\n          data-poster=\"${thumbUrl}\"\n          data-caption=\"${(reel.caption || \'\').replace(/\"/g, \'&quot;\')}\"\n          onclick=\"npxChangeReel(this)\">\n          <div class=\"npx-related-thumb\" style=\"padding:0; overflow:hidden;\">\n            ${thumbUrl ? `<img src=\"${thumbUrl}\" style=\"width:100%;height:100%;object-fit:cover;\" referrerpolicy=\"no-referrer\" />` : \'\'}\n          </div>\n          <div class=\"npx-related-info\" style=\"min-width:0;\">\n            <p style=\"white-space:nowrap;overflow:hidden;text-overflow:ellipsis;\">${title}</p>\n            <span>Play Reel</span>\n          </div>\n        </div>\n      `;\n      listContainer.innerHTML += itemHtml;\n\n      // Automatically load the first reel into the main viewer\n      if (index === 0) {\n        // Find the newly added element and trigger click\n        const firstReelEl = listContainer.querySelector(\'.npx-related-item\');\n        if (firstReelEl) npxChangeReel(firstReelEl);\n      }\n    });\n  }\n\n  // Fetch reels when page loads\n  document.addEventListener(\'DOMContentLoaded\', fetchLatestReels);\n\n  // ==========================================\n  // EXISTING FUNCTIONS\n  // ==========================================\n  function npxLoadReel() {\n    const token = document.getElementById(\'npxIgToken\').value.trim();\n    const mediaId = document.getElementById(\'npxMediaId\').value.trim();\n    const frame = document.getElementById(\'npxReelFrame\');\n    const placeholder = document.getElementById(\'npxReelPlaceholder\');\n\n    if (!token || !mediaId) {\n      placeholder.querySelector(\'span\').textContent = \'Please enter both token and media ID.\';\n      return;\n    }\n\n    placeholder.querySelector(\'span\').textContent = \'Loading reel...\';\n\n    const existing = frame.querySelector(\'iframe\');\n    if (existing) existing.remove();\n\n    const url = `https://www.instagram.com/p/${mediaId}/embed/`;\n    const iframe = document.createElement(\'iframe\');\n    iframe.src = url;\n    iframe.style.cssText = \'width:100%;height:100%;border:none;border-radius:14px;\';\n    iframe.allow = \'autoplay; encrypted-media\';\n    iframe.onload = () => { placeholder.style.display = \'none\'; };\n    iframe.onerror = () => { placeholder.querySelector(\'span\').textContent = \'Could not load reel. Check your media ID.\'; };\n    frame.insertBefore(iframe, frame.querySelector(\'.npx-play-btn\'));\n  }\n\n  function npxOpenLink(url) {\n    window.open(url, \'_blank\');\n  }\n\n  function npxSelectSlot(element) {\n    document.querySelectorAll(\'.npx-slot-pill.npx-avail\').forEach(el => {\n      el.classList.remove(\'npx-selected\');\n    });\n    element.classList.add(\'npx-selected\');\n\n    const btn = document.querySelector(\'.npx-appt-btn\');\n    btn.innerHTML = \'<svg viewBox=\"0 0 24 24\"><path d=\"M19 4h-1V2h-2v2H8V2H6v2H5c-1.11 0-2 .89-2 2v14c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2V6c0-1.11-.9-2-2-2zm0 16H5V10h14v10z\"/></svg> Book for \' + element.innerText;\n  }\n\n  function npxChangeReel(element) {\n    const media = element.getAttribute(\'data-media\');\n    const poster = element.getAttribute(\'data-poster\');\n    const captionRaw = element.getAttribute(\'data-caption\') || \'Instagram Reel\';\n\n    // Update video source\n    const video = document.querySelector(\'#npxReelFrame video\');\n    video.src = media;\n    video.poster = poster;\n    video.load();\n\n    // 1. Try to play with sound ON by default\n    video.muted = false;\n\n    video.play().catch(e => {\n      console.log(\'Browser blocked autoplay with sound. Falling back to muted autoplay.\');\n      // 2. If the browser blocks it (because the user hasn\'t clicked anything yet), \n      //    fallback to playing it muted so the video at least plays.\n      video.muted = true;\n      video.play().catch(err => console.log(\'Autoplay completely blocked:\', err));\n    });\n\n    // Parse caption and hashtags\n    let title = captionRaw.replace(/#\\w+/g, \'\').trim();\n    if (title.length > 65) title = title.substring(0, 65) + \'...\';\n    if (title.length === 0) title = \'Instagram Reel\';\n\n    document.querySelector(\'#npxVideoMeta h3\').innerText = title;\n    document.getElementById(\'npxCaptionText\').innerText = captionRaw.replace(/#\\w+/g, \'\').trim();\n\n    // Extract hashtags and update UI\n    const hashtags = captionRaw.match(/#\\w+/g) || [];\n    const tagsHtml = hashtags.map(t => `<span class=\"npx-hashtag\">${t}</span>`).join(\'\');\n    document.querySelector(\'.npx-hashtags\').innerHTML = tagsHtml;\n\n    // Randomize stats slightly to feel dynamic\n    document.getElementById(\'npxStatViews\').innerText = Math.floor(Math.random() * 50 + 5) + \'K\';\n    document.getElementById(\'npxStatLikes\').innerText = Math.floor(Math.random() * 900 + 100);\n    document.getElementById(\'npxStatComments\').innerText = Math.floor(Math.random() * 150 + 10);\n  }\n</script>', '2026-05-21 07:22:12');
INSERT INTO `banner_code_snapshot` (`id`, `code_content`, `created_at`) VALUES
(77, '<style>\n  @import url(\'https://fonts.googleapis.com/css2?family=Playfair+Display:wght@600;700&family=DM+Sans:wght@300;400;500&display=swap\');\n\n  :root {\n    --npx-c1: #0f0f0f;\n    --npx-c2: #1a1a2e;\n    --npx-c3: #16213e;\n    --npx-c4: #0f3460;\n    --npx-acc: #e94560;\n    --npx-acc2: #f5a623;\n    --npx-light: #f8f4ef;\n    --npx-muted: #a0a0b0;\n  }\n\n  .npx-popup-backdrop,\n  .npx-popup-backdrop * {\n    box-sizing: border-box;\n    margin: 0;\n    padding: 0;\n  }\n\n  .npx-popup-backdrop {\n    font-family: \'DM Sans\', sans-serif;\n    /* position: fixed; */\n    top: 0;\n    left: 0;\n    /* width: 100vw;\n    height: 100vh; */\n    background: rgba(0, 0, 0, 0.75);\n    backdrop-filter: blur(8px);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    z-index: 9999;\n    /* padding: 20px; */\n  }\n\n  .npx-popup-overlay {\n    background: rgba(10, 10, 20, 0.92);\n    border-radius: 20px;\n    overflow: hidden;\n    display: flex;\n    flex-direction: column;\n    min-height: 580px;\n    width: 100%;\n    max-width: 900px;\n    border: 1px solid rgba(255, 255, 255, 0.08);\n    position: relative;\n    box-shadow: 0 30px 60px rgba(0, 0, 0, 0.5);\n    animation: npxPopIn 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;\n  }\n\n  @keyframes npxPopIn {\n    0% {\n      opacity: 0;\n      transform: scale(0.9) translateY(20px);\n    }\n\n    100% {\n      opacity: 1;\n      transform: scale(1) translateY(0);\n    }\n  }\n\n  .npx-skeleton {\n    display: flex;\n    flex-direction: column;\n    width: 100%;\n    gap: 12px;\n    animation: npxPulse 1.5s infinite ease-in-out;\n  }\n\n  .npx-skel-line {\n    background: rgba(255, 255, 255, 0.08);\n    border-radius: 6px;\n  }\n\n  @keyframes npxPulse {\n    0% {\n      opacity: 0.5;\n    }\n\n    50% {\n      opacity: 1;\n    }\n\n    100% {\n      opacity: 0.5;\n    }\n  }\n\n  .npx-popup-header {\n    background: linear-gradient(90deg, #0f3460, #16213e);\n    padding: 14px 22px;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    border-bottom: 1px solid rgba(255, 255, 255, 0.07);\n  }\n\n  .npx-popup-header h2 {\n    font-family: \'Playfair Display\', serif;\n    font-size: 17px;\n    color: #fff;\n    letter-spacing: 0.3px;\n  }\n\n  .npx-live-badge {\n    background: var(--npx-acc);\n    color: #fff;\n    font-size: 10px;\n    font-weight: 500;\n    padding: 3px 10px;\n    border-radius: 20px;\n    display: flex;\n    align-items: center;\n    gap: 5px;\n    letter-spacing: 0.5px;\n  }\n\n  .npx-live-dot {\n    width: 6px;\n    height: 6px;\n    border-radius: 50%;\n    background: #fff;\n    animation: npxBlink 1.2s infinite;\n  }\n\n  @keyframes npxBlink {\n\n    0%,\n    100% {\n      opacity: 1;\n    }\n\n    50% {\n      opacity: 0.2;\n    }\n  }\n\n  .npx-popup-close {\n    width: 28px;\n    height: 28px;\n    border-radius: 50%;\n    border: 1px solid rgba(255, 255, 255, 0.15);\n    background: rgba(255, 255, 255, 0.06);\n    color: #ccc;\n    font-size: 16px;\n    cursor: pointer;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    line-height: 1;\n  }\n\n  .npx-popup-body {\n    display: grid;\n    grid-template-columns: minmax(0, 2fr) minmax(260px, 1fr);\n    flex: 1;\n    min-height: 0;\n  }\n\n  .npx-left-panel {\n    display: grid;\n    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);\n    border-right: 1px solid rgba(255, 255, 255, 0.07);\n    min-width: 0;\n  }\n\n  .npx-reel-section {\n    background: #0a0a14;\n    padding: 18px 16px;\n    border-right: 1px solid rgba(255, 255, 255, 0.06);\n    display: flex;\n    flex-direction: column;\n    gap: 12px;\n  }\n\n  .npx-section-label {\n    font-size: 10px;\n    text-transform: uppercase;\n    letter-spacing: 1.5px;\n    color: var(--npx-muted);\n    display: flex;\n    align-items: center;\n    gap: 6px;\n  }\n\n  .npx-section-label svg {\n    width: 12px;\n    height: 12px;\n    fill: var(--npx-acc);\n  }\n\n  .npx-reel-frame {\n    background: #111;\n    border-radius: 14px;\n    overflow: hidden;\n    position: relative;\n    aspect-ratio: 9/14;\n    border: 1px solid rgba(255, 255, 255, 0.08);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    cursor: pointer;\n  }\n\n  .npx-reel-placeholder {\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 10px;\n    color: rgba(255, 255, 255, 0.3);\n  }\n\n  .npx-reel-placeholder svg {\n    width: 36px;\n    height: 36px;\n    opacity: 0.4;\n  }\n\n  .npx-reel-placeholder span {\n    font-size: 11px;\n    text-align: center;\n    max-width: 110px;\n    line-height: 1.5;\n  }\n\n  .npx-reel-frame .npx-play-btn {\n    width: 48px;\n    height: 48px;\n    border-radius: 50%;\n    background: rgba(233, 69, 96, 0.85);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    position: absolute;\n    bottom: 14px;\n    right: 14px;\n    cursor: pointer;\n    transition: transform 0.15s;\n  }\n\n  .npx-reel-frame .npx-play-btn:hover {\n    transform: scale(1.1);\n  }\n\n  .npx-play-btn svg {\n    width: 18px;\n    height: 18px;\n    fill: #fff;\n    margin-left: 2px;\n  }\n\n  .npx-token-form {\n    display: flex;\n    flex-direction: column;\n    gap: 6px;\n  }\n\n  .npx-token-form label {\n    font-size: 10px;\n    color: var(--npx-muted);\n    letter-spacing: 0.5px;\n  }\n\n  .npx-token-form input {\n    background: rgba(255, 255, 255, 0.05);\n    border: 1px solid rgba(255, 255, 255, 0.1);\n    border-radius: 8px;\n    color: #fff;\n    font-size: 11px;\n    padding: 7px 10px;\n    font-family: monospace;\n    outline: none;\n    width: 100%;\n    transition: border-color 0.2s;\n  }\n\n  .npx-token-form input:focus {\n    border-color: var(--npx-acc);\n  }\n\n  .npx-token-form button {\n    background: var(--npx-acc);\n    color: #fff;\n    border: none;\n    border-radius: 8px;\n    padding: 7px;\n    font-size: 11px;\n    font-family: \'DM Sans\', sans-serif;\n    cursor: pointer;\n    font-weight: 500;\n    transition: opacity 0.2s;\n    margin-top: 2px;\n  }\n\n  .npx-token-form button:hover {\n    opacity: 0.85;\n  }\n\n  .npx-info-section {\n    background: #0d0d1a;\n    padding: 18px 16px;\n    display: flex;\n    flex-direction: column;\n    gap: 14px;\n    overflow-y: auto;\n    overflow-x: hidden;\n    max-height: 100%;\n  }\n\n  .npx-info-section::-webkit-scrollbar {\n    width: 4px;\n  }\n\n  .npx-info-section::-webkit-scrollbar-track {\n    background: transparent;\n  }\n\n  .npx-info-section::-webkit-scrollbar-thumb {\n    background: rgba(255, 255, 255, 0.1);\n    border-radius: 4px;\n  }\n\n  .npx-video-meta {\n    display: flex;\n    flex-direction: column;\n    gap: 4px;\n  }\n\n  .npx-video-meta h3 {\n    font-family: \'Playfair Display\', serif;\n    font-size: 14px;\n    color: #fff;\n    line-height: 1.4;\n  }\n\n  .npx-video-meta .npx-handle {\n    font-size: 11px;\n    color: var(--npx-acc2);\n  }\n\n  .npx-stat-row {\n    display: flex;\n    gap: 8px;\n    flex-wrap: wrap;\n  }\n\n  .npx-stat-chip {\n    background: rgba(255, 255, 255, 0.05);\n    border: 1px solid rgba(255, 255, 255, 0.08);\n    border-radius: 8px;\n    padding: 6px 10px;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 1px;\n    flex: 1;\n    min-width: 52px;\n  }\n\n  .npx-stat-chip .npx-val {\n    font-size: 13px;\n    font-weight: 500;\n    color: #fff;\n  }\n\n  .npx-stat-chip .npx-lbl {\n    font-size: 9px;\n    color: var(--npx-muted);\n    text-transform: uppercase;\n    letter-spacing: 0.8px;\n  }\n\n  .npx-caption-box {\n    background: rgba(255, 255, 255, 0.03);\n    border: 1px solid rgba(255, 255, 255, 0.06);\n    border-radius: 10px;\n    padding: 10px;\n  }\n\n  .npx-caption-box p {\n    font-size: 11px;\n    color: rgba(255, 255, 255, 0.55);\n    line-height: 1.7;\n  }\n\n  .npx-caption-box .npx-hashtags {\n    margin-top: 6px;\n    display: flex;\n    flex-wrap: wrap;\n    gap: 4px;\n  }\n\n  .npx-hashtag {\n    font-size: 10px;\n    color: var(--npx-acc2);\n    background: rgba(245, 166, 35, 0.08);\n    border: 1px solid rgba(245, 166, 35, 0.15);\n    border-radius: 6px;\n    padding: 2px 7px;\n  }\n\n  .npx-related-title {\n    font-size: 10px;\n    text-transform: uppercase;\n    letter-spacing: 1px;\n    color: var(--npx-muted);\n  }\n\n  .npx-related-list {\n    display: flex;\n    flex-direction: row;\n    gap: 12px;\n    overflow-x: auto;\n    scroll-behavior: smooth;\n    scroll-snap-type: x mandatory;\n    padding-bottom: 8px;\n  }\n\n  .npx-related-list::-webkit-scrollbar {\n    height: 4px;\n  }\n\n  .npx-related-list::-webkit-scrollbar-track {\n    background: rgba(255, 255, 255, 0.05);\n    border-radius: 4px;\n  }\n\n  .npx-related-list::-webkit-scrollbar-thumb {\n    background: rgba(255, 255, 255, 0.2);\n    border-radius: 4px;\n  }\n\n  .npx-related-item {\n    display: flex;\n    flex-direction: column;\n    gap: 6px;\n    align-items: stretch;\n    padding: 6px;\n    border-radius: 8px;\n    background: rgba(255, 255, 255, 0.03);\n    border: 1px solid rgba(255, 255, 255, 0.05);\n    cursor: pointer;\n    transition: background 0.15s, transform 0.15s;\n    flex: 0 0 90px;\n    scroll-snap-align: start;\n  }\n\n  .npx-related-item:hover {\n    background: rgba(255, 255, 255, 0.07);\n    transform: translateY(-2px);\n  }\n\n  .npx-related-thumb {\n    width: 100%;\n    height: 138px;\n    border-radius: 4px;\n    background: linear-gradient(135deg, #1a1a3e, #0f3460);\n    flex-shrink: 0;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    overflow: hidden;\n  }\n\n  .npx-related-thumb svg {\n    width: 14px;\n    height: 14px;\n    fill: rgba(255, 255, 255, 0.4);\n  }\n\n  .npx-related-info p {\n    font-size: 10px;\n    color: rgba(255, 255, 255, 0.7);\n    line-height: 1.3;\n    white-space: nowrap;\n    overflow: hidden;\n    text-overflow: ellipsis;\n  }\n\n  .npx-related-info span {\n    font-size: 10px;\n    color: var(--npx-muted);\n  }\n\n  .npx-right-panel {\n    background: linear-gradient(160deg, #0a0a18 0%, #0f1a35 50%, #0a0a18 100%);\n    padding: 30px 20px;\n    display: block;\n    text-align: center;\n    min-width: 250px;\n    position: relative;\n  }\n\n  .npx-right-panel::before {\n    content: \'\';\n    position: absolute;\n    top: -60px;\n    left: 50%;\n    transform: translateX(-50%);\n    width: 180px;\n    height: 180px;\n    border-radius: 50%;\n    background: radial-gradient(circle, rgba(233, 69, 96, 0.12), transparent 70%);\n    pointer-events: none;\n  }\n\n  .npx-appt-top {\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 12px;\n    padding-top: 8px;\n    margin-bottom: 24px;\n  }\n\n  .npx-appt-icon {\n    width: 52px;\n    height: 52px;\n    border-radius: 16px;\n    background: rgba(233, 69, 96, 0.12);\n    border: 1px solid rgba(233, 69, 96, 0.25);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n\n  .npx-appt-icon svg {\n    width: 26px;\n    height: 26px;\n    fill: var(--npx-acc);\n  }\n\n  .npx-appt-title {\n    font-family: \'Playfair Display\', serif;\n    font-size: 15px;\n    color: #fff;\n    line-height: 1.4;\n  }\n\n  .npx-appt-sub {\n    font-size: 11px;\n    color: var(--npx-muted);\n    line-height: 1.6;\n  }\n\n  .npx-appt-features {\n    display: flex;\n    flex-direction: column;\n    gap: 7px;\n    width: 100%;\n    margin-bottom: 24px;\n  }\n\n  .npx-appt-feat {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    font-size: 11px;\n    color: rgba(255, 255, 255, 0.6);\n  }\n\n  .npx-feat-dot {\n    width: 5px;\n    height: 5px;\n    border-radius: 50%;\n    background: var(--npx-acc2);\n    flex-shrink: 0;\n  }\n\n  .npx-slots-preview {\n    width: 100%;\n    background: rgba(255, 255, 255, 0.03);\n    border: 1px solid rgba(255, 255, 255, 0.07);\n    border-radius: 10px;\n    padding: 10px;\n    margin-bottom: 24px;\n  }\n\n  .npx-slots-label {\n    font-size: 9px;\n    color: var(--npx-muted);\n    text-transform: uppercase;\n    letter-spacing: 1px;\n    margin-bottom: 6px;\n  }\n\n  .npx-slot-pills {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 4px;\n  }\n\n  .npx-slot-pill {\n    font-size: 10px;\n    padding: 3px 8px;\n    border-radius: 6px;\n    border: 1px solid rgba(255, 255, 255, 0.1);\n    color: rgba(255, 255, 255, 0.5);\n    transition: all 0.2s ease;\n  }\n\n  .npx-slot-pill.npx-avail {\n    border-color: rgba(15, 180, 100, 0.3);\n    color: rgba(15, 200, 120, 0.8);\n    background: rgba(15, 180, 100, 0.07);\n    cursor: pointer;\n  }\n\n  .npx-slot-pill.npx-avail:hover {\n    background: rgba(15, 180, 100, 0.15);\n    border-color: rgba(15, 180, 100, 0.5);\n    transform: translateY(-1px);\n  }\n\n  .npx-slot-pill.npx-avail.npx-selected {\n    background: var(--npx-acc);\n    border-color: var(--npx-acc);\n    color: #fff;\n    box-shadow: 0 4px 10px rgba(233, 69, 96, 0.3);\n  }\n\n  .npx-appt-btn {\n    width: 100%;\n    background: var(--npx-acc);\n    color: #fff;\n    border: none;\n    border-radius: 12px;\n    padding: 13px;\n    font-size: 13px;\n    font-weight: 500;\n    font-family: \'DM Sans\', sans-serif;\n    cursor: pointer;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    gap: 7px;\n    transition: transform 0.15s, opacity 0.15s;\n    letter-spacing: 0.2px;\n  }\n\n  .npx-appt-btn:hover {\n    opacity: 0.9;\n    transform: translateY(-1px);\n  }\n\n  .npx-appt-btn:active {\n    transform: scale(0.98);\n  }\n\n  .npx-appt-btn svg {\n    width: 16px;\n    height: 16px;\n    fill: #fff;\n  }\n\n  .npx-appt-note {\n    font-size: 10px;\n    color: rgba(255, 255, 255, 0.25);\n    line-height: 1.5;\n  }\n\n  @media (max-width: 850px) {\n    .npx-popup-body {\n      grid-template-columns: 1fr;\n    }\n\n    .npx-left-panel {\n      grid-template-columns: 1fr;\n      border-right: none;\n      border-bottom: 1px solid rgba(255, 255, 255, 0.07);\n    }\n\n    .npx-popup-overlay {\n      height: 90vh;\n      overflow-y: auto;\n      max-width: 95vw;\n    }\n\n    .npx-right-panel {\n      padding: 30px 16px;\n      gap: 20px;\n    }\n\n    .npx-reel-frame {\n      width: 100%;\n      height: 100%;\n    }\n  }\n</style>\n\n<h2 class=\"npx-sr-only\"\n  style=\"position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border-width:0;\">\n  Latest news popup with Instagram reel viewer and appointment booking</h2>\n\n<div class=\"npx-popup-backdrop\" id=\"npxPopupBackdrop\">\n  <div class=\"npx-popup-overlay\">\n\n    <div class=\"npx-popup-body\">\n\n      <div class=\"npx-left-panel\">\n\n        <!-- INSTAGRAM REEL SIDE -->\n        <div class=\"npx-reel-section\" style=\"justify-content: center; padding: 0;\">\n          <div class=\"npx-reel-frame\" id=\"npxReelFrame\"\n            style=\"height: 100%; border-radius: 0; border-right: 1px solid rgba(255, 255, 255, 0.08); overflow: hidden;\">\n\n            <!-- VIDEO SKELETON LOADER -->\n            <div id=\"npxVideoSkeleton\"\n              style=\"width: 100%; height: 100%; background: rgba(255, 255, 255, 0.05); animation: npxPulse 1.5s infinite ease-in-out;\">\n            </div>\n\n            <video id=\"npxMainVideo\"\n              src=\"https://instagram.fdel1-7.fna.fbcdn.net/o1/v/t2/f2/m86/AQO5sIiKbPw1xkABk9k7Sl_Og_DC_-z2-XmV5EQV3OgwjGuIKWMDSfwNTegQ460MWu4uT421GlSfFsw3STzmfFxVlb8wmNWzjzQZtsk.mp4?_nc_cat=103&_nc_oc=AdpOCAB9FAiyBIZdm03WcZKCyDNMZimduxyi3ul9tcJ_69injBOV6gd5WZNfL-cUH1PD8tkVo4gjACEu9bfhaxbE&_nc_sid=5e9851&_nc_ht=instagram.fdel1-7.fna.fbcdn.net&_nc_ohc=2kLsowPX0VIQ7kNvwGI-9AF&efg=eyJ2ZW5jb2RlX3RhZyI6Inhwdl9wcm9ncmVzc2l2ZS5JTlNUQUdSQU0uQ0xJUFMuQzMuNzIwLmRhc2hfYmFzZWxpbmVfMV92MSIsInhwdl9hc3NldF9pZCI6MTc5MTM3NTM1MTMzNjQ3NDMsImFzc2V0X2FnZV9kYXlzIjozLCJ2aV91c2VjYXNlX2lkIjoxMDA5OSwiZHVyYXRpb25fcyI6ODksInVybGdlbl9zb3VyY2UiOiJ3d3cifQ%3D%3D&ccb=17-1&vs=35508edcd865211d&_nc_&_nc_gid=6zF1FeT4mOtd7D9M4acWzQ&edm=ANQ71j8EAAAA&_nc_zt=28&_nc_tpa=Q5bMBQFJGIg9ypkpDPIyibfpxGJZt8I1UOMdB18a0nq1rOQFPJC6F7KDgXEcl-GwAw5Ch2jFKjcF6JrlzA&oh=00_Af3iKm-2V2vnHbFsJZ-giGoqYRj24U_N5c59J6pGZhMytQ&oe=69F10D18\"\n              poster=\"https://scontent.cdninstagram.com/v/t51.82787-15/672336940_17913753534364743_7989516135913121464_n.jpg?stp=dst-jpg_e35_tt6&_nc_cat=102&ccb=7-5&_nc_sid=18de74&efg=eyJlZmdfdGFnIjoiQ0xJUFMuYmVzdF9pbWFnZV91cmxnZW4uQzMifQ%3D%3D&_nc_ohc=1zhwq2Ng-t4Q7kNvwGoLkpr&_nc_oc=AdqSGR7_l5tiEmor48v7M2-AxPD3H2aoaZ-WWkrbEq1zXTWvnfBLU6wkpYqm3NBU_dn6XUdf69SQp8z-T55IqcA1&_nc_zt=23&_nc_ht=scontent.cdninstagram.com&edm=ANQ71j8EAAAA&_nc_gid=6zF1FeT4mOtd7D9M4acWzQ&_nc_tpa=Q5bMBQFJYeYe5YUHF-FncYjnzEpzJTheHmoL-2pSw_HC84XlYIo95YvJ4UqQOK_iRLcCAdT4hwvMxU5Y7A&oh=00_Af3xIWfHQhnu5gVWWjdKwZpbyX8uYo7isef6bvvWBfdz5A&oe=69F515FA\"\n              style=\"display: none; width: 100%; height: 100%; object-fit: cover; cursor: pointer;\" autoplay loop\n              playsinline referrerpolicy=\"no-referrer\" onclick=\"this.muted = !this.muted\" title=\"Click to toggle sound\">\n            </video>\n          </div>\n\n          <!-- <div class=\"npx-token-form\">\n            <label>Instagram Access Token</label>\n            <input type=\"text\" id=\"npxIgToken\" placeholder=\"EAABs...\" />\n            <input type=\"text\" id=\"npxMediaId\" placeholder=\"Media ID or Reel URL\" style=\"margin-top:4px\" />\n            <button onclick=\"npxLoadReel()\">Load Reel</button>\n          </div> -->\n        </div>\n\n        <!-- VIDEO INFO SIDE -->\n        <div class=\"npx-info-section\">\n\n          <!-- SKELETON LOADER -->\n          <div class=\"npx-skeleton\" id=\"npxSkeleton\">\n            <div class=\"npx-skel-line\" style=\"width: 40%; height: 16px; margin-bottom: 20px;\"></div>\n            <div class=\"npx-skel-line\" style=\"width: 80%; height: 24px; margin-bottom: 8px;\"></div>\n            <div class=\"npx-skel-line\" style=\"width: 30%; height: 14px; margin-bottom: 20px;\"></div>\n            <div style=\"display: flex; gap: 8px; margin-bottom: 20px;\">\n              <div class=\"npx-skel-line\" style=\"flex: 1; height: 36px;\"></div>\n              <div class=\"npx-skel-line\" style=\"flex: 1; height: 36px;\"></div>\n              <div class=\"npx-skel-line\" style=\"flex: 1; height: 36px;\"></div>\n            </div>\n            <div class=\"npx-skel-line\" style=\"width: 100%; height: 60px; margin-bottom: 20px;\"></div>\n            <div class=\"npx-skel-line\" style=\"width: 50%; height: 16px; margin-bottom: 12px;\"></div>\n            <div style=\"display: flex; gap: 12px; overflow: hidden;\">\n              <div class=\"npx-skel-line\" style=\"min-width: 90px; height: 140px; border-radius: 8px;\"></div>\n              <div class=\"npx-skel-line\" style=\"min-width: 90px; height: 140px; border-radius: 8px;\"></div>\n              <div class=\"npx-skel-line\" style=\"min-width: 90px; height: 140px; border-radius: 8px;\"></div>\n            </div>\n          </div>\n\n          <!-- ACTUAL CONTENT -->\n          <div id=\"npxInfoContent\" style=\"display: none; flex-direction: column; gap: 14px; width: 100%;\">\n            <div class=\"npx-section-label\">\n              <svg viewBox=\"0 0 24 24\">\n                <path d=\"M13 2.003A10 10 0 1 0 22 12 10 10 0 0 0 13 2.003zm-1 14.5v-9l6 4.5z\" />\n              </svg>\n              Video Info\n            </div>\n\n            <div class=\"npx-video-meta\" id=\"npxVideoMeta\">\n              <h3>Call Sirf 11.00 Baje Se Shaam 6.00 Baje Tak hi kare</h3>\n              <span class=\"npx-handle\">@avisaexperts</span>\n            </div>\n\n            <div class=\"npx-stat-row\">\n              <div class=\"npx-stat-chip\"><span class=\"npx-val\" id=\"npxStatViews\">12K</span><span\n                  class=\"npx-lbl\">Views</span></div>\n              <div class=\"npx-stat-chip\"><span class=\"npx-val\" id=\"npxStatLikes\">850</span><span\n                  class=\"npx-lbl\">Likes</span></div>\n              <div class=\"npx-stat-chip\"><span class=\"npx-val\" id=\"npxStatComments\">124</span><span\n                  class=\"npx-lbl\">Comments</span></div>\n            </div>\n\n            <div class=\"npx-caption-box\">\n              <p id=\"npxCaptionText\">Call Sirf 11.00 Baje Se Shaam 6.00 Baje Tak hi kare</p>\n              <div class=\"npx-hashtags\">\n                <span class=\"npx-hashtag\">#viralvideos</span>\n                <span class=\"npx-hashtag\">#visa</span>\n                <span class=\"npx-hashtag\">#famous</span>\n                <span class=\"npx-hashtag\">#avisaexperts</span>\n                <span class=\"npx-hashtag\">#kaveeshkapoor</span>\n              </div>\n            </div>\n\n            <div>\n              <p class=\"npx-related-title\">More from this creator</p>\n              <div class=\"npx-related-list\">\n                <!-- Hardcoded reels will be replaced by JS -->\n              </div>\n            </div>\n          </div>\n        </div>\n\n      </div>\n\n      <!-- RIGHT: BOOK APPOINTMENT -->\n      <div class=\"npx-right-panel\">\n\n        <div class=\"npx-appt-top\">\n          <div class=\"npx-appt-icon\">\n            <svg viewBox=\"0 0 24 24\">\n              <path\n                d=\"M19 4h-1V2h-2v2H8V2H6v2H5c-1.11 0-2 .89-2 2v14c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2V6c0-1.11-.9-2-2-2zm0 16H5V10h14v10zm0-12H5V6h14v2zM7 12h5v5H7z\" />\n            </svg>\n          </div>\n          <div>\n            <p class=\"npx-appt-title\">Book a<br />Consultation</p>\n            <p class=\"npx-appt-sub\">Talk to an expert.<br />Free 30-min session.</p>\n          </div>\n        </div>\n\n        <div class=\"npx-appt-features\">\n          <div class=\"npx-appt-feat\"><span class=\"npx-feat-dot\"></span>Choose your preferred time</div>\n          <div class=\"npx-appt-feat\"><span class=\"npx-feat-dot\"></span>Video or in-person meeting</div>\n          <div class=\"npx-appt-feat\"><span class=\"npx-feat-dot\"></span>Instant confirmation</div>\n          <div class=\"npx-appt-feat\"><span class=\"npx-feat-dot\"></span>No payment required</div>\n        </div>\n\n        <div class=\"npx-slots-preview\">\n          <p class=\"npx-slots-label\">Available Today</p>\n          <div class=\"npx-slot-pills\">\n            <span class=\"npx-slot-pill npx-avail\" onclick=\"npxSelectSlot(this)\">10:00 AM</span>\n            <span class=\"npx-slot-pill\" title=\"Not available\">11:30 AM</span>\n            <span class=\"npx-slot-pill npx-avail\" onclick=\"npxSelectSlot(this)\">2:00 PM</span>\n            <span class=\"npx-slot-pill npx-avail\" onclick=\"npxSelectSlot(this)\">4:30 PM</span>\n            <span class=\"npx-slot-pill\" title=\"Not available\">6:00 PM</span>\n          </div>\n        </div>\n\n        <div style=\"width:100%;display:flex;flex-direction:column;gap:8px\">\n          <button class=\"npx-appt-btn\" onclick=\"npxOpenLink(\'https://avisaexperts.com/appointment.php\')\">\n            <svg viewBox=\"0 0 24 24\">\n              <path\n                d=\"M19 4h-1V2h-2v2H8V2H6v2H5c-1.11 0-2 .89-2 2v14c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2V6c0-1.11-.9-2-2-2zm0 16H5V10h14v10z\" />\n            </svg>\n            Book Appointment\n          </button>\n          <p class=\"npx-appt-note\">Opens full booking page in a new tab</p>\n        </div>\n\n      </div>\n\n    </div>\n  </div>\n</div>\n\n<script>\n  // ==========================================\n  // DYNAMIC INSTAGRAM FETCHING LOGIC\n  // ==========================================\n  const IG_CONFIG = {\n    // ⚠️ Replace this with your actual Instagram Access Token\n    accessToken: \'IGAAWp7Lk0ae5BZAFpGMzlFQ21LMWdXYXFUYzBKU3c0WWFuc0k4ZAWl6eU5Hal9NVWE5LWVVc2lUNm9FNUxncVVIYlk0ZAkJBWHdhMDB1X2MwT0UtQVV4QmdJMW1qeGZAwb2lFMVBrUXdmWkdmelliTE9ISTd1QlI0VmdiMlJzSFU3NAZDZD\',\n    limit: 5 // How many posts to fetch\n  };\n\n  function showInfoContent() {\n    // Right panel\n    const skel = document.getElementById(\'npxSkeleton\');\n    const cont = document.getElementById(\'npxInfoContent\');\n    if (skel) skel.style.display = \'none\';\n    if (cont) cont.style.display = \'flex\';\n\n    // Left panel video\n    const vidSkel = document.getElementById(\'npxVideoSkeleton\');\n    const mainVid = document.getElementById(\'npxMainVideo\');\n    if (vidSkel) vidSkel.style.display = \'none\';\n    if (mainVid) mainVid.style.display = \'block\';\n  }\n\n  async function fetchLatestReels() {\n    if (!IG_CONFIG.accessToken || IG_CONFIG.accessToken === \'YOUR_INSTAGRAM_ACCESS_TOKEN\') {\n      console.warn(\'Instagram Access Token missing. Using hardcoded static reels as fallback.\');\n      showInfoContent();\n      return;\n    }\n\n    try {\n      // Fetch media from Instagram Graph API\n      const response = await fetch(`https://graph.instagram.com/me/media?fields=id,caption,media_type,media_url,thumbnail_url,timestamp&limit=${IG_CONFIG.limit}&access_token=${IG_CONFIG.accessToken}`);\n      const data = await response.json();\n\n      if (data.error) {\n        console.error(\'Error fetching Instagram data:\', data.error.message);\n        showInfoContent();\n        return;\n      }\n\n      // Filter only videos (reels)\n      const reels = data.data.filter(item => item.media_type === \'VIDEO\');\n\n      if (reels.length > 0) {\n        populateReelsUI(reels);\n        showInfoContent();\n      } else {\n        showInfoContent();\n      }\n    } catch (error) {\n      console.error(\'Network error fetching reels:\', error);\n      showInfoContent();\n    }\n  }\n\n  function populateReelsUI(reels) {\n    const listContainer = document.querySelector(\'.npx-related-list\');\n    listContainer.innerHTML = \'\'; // Clear hardcoded reels\n\n    reels.forEach((reel, index) => {\n      // Create thumbnail HTML\n      const thumbUrl = reel.thumbnail_url || \'\';\n      let title = (reel.caption || \'\').replace(/#\\w+/g, \'\').trim();\n      if (title.length > 20) title = title.substring(0, 20) + \'...\';\n      if (!title) title = \'Instagram Reel\';\n\n      const itemHtml = `\n        <div class=\"npx-related-item\"\n          data-media=\"${reel.media_url}\"\n          data-poster=\"${thumbUrl}\"\n          data-caption=\"${(reel.caption || \'\').replace(/\"/g, \'&quot;\')}\"\n          onclick=\"npxChangeReel(this)\">\n          <div class=\"npx-related-thumb\" style=\"padding:0; overflow:hidden;\">\n            ${thumbUrl ? `<img src=\"${thumbUrl}\" style=\"width:100%;height:100%;object-fit:cover;\" referrerpolicy=\"no-referrer\" />` : \'\'}\n          </div>\n          <div class=\"npx-related-info\" style=\"min-width:0;\">\n            <p style=\"white-space:nowrap;overflow:hidden;text-overflow:ellipsis;\">${title}</p>\n            <span>Play Reel</span>\n          </div>\n        </div>\n      `;\n      listContainer.innerHTML += itemHtml;\n\n      // Automatically load the first reel into the main viewer\n      if (index === 0) {\n        // Find the newly added element and trigger click\n        const firstReelEl = listContainer.querySelector(\'.npx-related-item\');\n        if (firstReelEl) npxChangeReel(firstReelEl);\n      }\n    });\n  }\n\n  // Fetch reels when page loads\n  document.addEventListener(\'DOMContentLoaded\', fetchLatestReels);\n\n  // ==========================================\n  // EXISTING FUNCTIONS\n  // ==========================================\n  function npxLoadReel() {\n    const token = document.getElementById(\'npxIgToken\').value.trim();\n    const mediaId = document.getElementById(\'npxMediaId\').value.trim();\n    const frame = document.getElementById(\'npxReelFrame\');\n    const placeholder = document.getElementById(\'npxReelPlaceholder\');\n\n    if (!token || !mediaId) {\n      placeholder.querySelector(\'span\').textContent = \'Please enter both token and media ID.\';\n      return;\n    }\n\n    placeholder.querySelector(\'span\').textContent = \'Loading reel...\';\n\n    const existing = frame.querySelector(\'iframe\');\n    if (existing) existing.remove();\n\n    const url = `https://www.instagram.com/p/${mediaId}/embed/`;\n    const iframe = document.createElement(\'iframe\');\n    iframe.src = url;\n    iframe.style.cssText = \'width:100%;height:100%;border:none;border-radius:14px;\';\n    iframe.allow = \'autoplay; encrypted-media\';\n    iframe.onload = () => { placeholder.style.display = \'none\'; };\n    iframe.onerror = () => { placeholder.querySelector(\'span\').textContent = \'Could not load reel. Check your media ID.\'; };\n    frame.insertBefore(iframe, frame.querySelector(\'.npx-play-btn\'));\n  }\n\n  function npxOpenLink(url) {\n    window.open(url, \'_blank\');\n  }\n\n  function npxSelectSlot(element) {\n    document.querySelectorAll(\'.npx-slot-pill.npx-avail\').forEach(el => {\n      el.classList.remove(\'npx-selected\');\n    });\n    element.classList.add(\'npx-selected\');\n\n    const btn = document.querySelector(\'.npx-appt-btn\');\n    btn.innerHTML = \'<svg viewBox=\"0 0 24 24\"><path d=\"M19 4h-1V2h-2v2H8V2H6v2H5c-1.11 0-2 .89-2 2v14c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2V6c0-1.11-.9-2-2-2zm0 16H5V10h14v10z\"/></svg> Book for \' + element.innerText;\n  }\n\n  function npxChangeReel(element) {\n    const media = element.getAttribute(\'data-media\');\n    const poster = element.getAttribute(\'data-poster\');\n    const captionRaw = element.getAttribute(\'data-caption\') || \'Instagram Reel\';\n\n    // Update video source\n    const video = document.querySelector(\'#npxReelFrame video\');\n    video.src = media;\n    video.poster = poster;\n    video.load();\n\n    // 1. Try to play with sound ON by default\n    video.muted = false;\n\n    video.play().catch(e => {\n      console.log(\'Browser blocked autoplay with sound. Falling back to muted autoplay.\');\n      // 2. If the browser blocks it (because the user hasn\'t clicked anything yet), \n      //    fallback to playing it muted so the video at least plays.\n      video.muted = true;\n      video.play().catch(err => console.log(\'Autoplay completely blocked:\', err));\n    });\n\n    // Parse caption and hashtags\n    let title = captionRaw.replace(/#\\w+/g, \'\').trim();\n    if (title.length > 65) title = title.substring(0, 65) + \'...\';\n    if (title.length === 0) title = \'Instagram Reel\';\n\n    document.querySelector(\'#npxVideoMeta h3\').innerText = title;\n    document.getElementById(\'npxCaptionText\').innerText = captionRaw.replace(/#\\w+/g, \'\').trim();\n\n    // Extract hashtags and update UI\n    const hashtags = captionRaw.match(/#\\w+/g) || [];\n    const tagsHtml = hashtags.map(t => `<span class=\"npx-hashtag\">${t}</span>`).join(\'\');\n    document.querySelector(\'.npx-hashtags\').innerHTML = tagsHtml;\n\n    // Randomize stats slightly to feel dynamic\n    document.getElementById(\'npxStatViews\').innerText = Math.floor(Math.random() * 50 + 5) + \'K\';\n    document.getElementById(\'npxStatLikes\').innerText = Math.floor(Math.random() * 900 + 100);\n    document.getElementById(\'npxStatComments\').innerText = Math.floor(Math.random() * 150 + 10);\n  }\n</script>', '2026-06-03 07:36:13'),
(83, '<link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\r\n\r\n<style>\r\n\r\n*{\r\nmargin:0;\r\npadding:0;\r\nbox-sizing:border-box;\r\nfont-family:\'Inter\',sans-serif;\r\n}\r\n\r\n.outer-layer{\r\nbackground:#f8fafc;\r\nmin-height:600px;\r\nposition:relative;\r\noverflow:hidden;\r\n}\r\n\r\n/* Hero */\r\n\r\n.avf-hero{\r\nposition:absolute;\r\ntop:50%;\r\nleft:50%;\r\ntransform:translate(-50%,-50%);\r\ntext-align:center;\r\nwidth:650px;\r\nmax-width:90%;\r\nz-index:5;\r\n}\r\n\r\n.avf-hero h1{\r\nfont-size:56px;\r\nfont-weight:700;\r\ncolor:#111827;\r\nmargin-bottom:18px;\r\n}\r\n\r\n.avf-hero p{\r\nfont-size:20px;\r\ncolor:#6b7280;\r\nline-height:32px;\r\n}\r\n\r\n/* Cards */\r\n\r\n.avf-profile{\r\nposition:absolute;\r\ndisplay:flex;\r\nalign-items:center;\r\ngap:14px;\r\nwidth:330px;\r\npadding:12px 16px;\r\nbackground:#fff;\r\nborder-radius:60px;\r\nborder:1px solid #e5e7eb;\r\nbox-shadow:0 10px 25px rgba(0,0,0,.06);\r\n}\r\n\r\n.avf-profile img{\r\nwidth:58px;\r\nheight:58px;\r\nborder-radius:50%;\r\nobject-fit:cover;\r\nborder:2px solid #E1306C;\r\n}\r\n\r\n.avf-info{\r\nflex:1;\r\n}\r\n\r\n.avf-info h3{\r\nfont-size:16px;\r\nfont-weight:600;\r\ncolor:#111827;\r\nwhite-space:nowrap;\r\n}\r\n\r\n.avf-info span{\r\nfont-size:14px;\r\ncolor:#6b7280;\r\nwhite-space:nowrap;\r\n}\r\n\r\n.avf-follow{\r\npadding:10px 18px;\r\nbackground:#0095F6;\r\ncolor:#fff;\r\ntext-decoration:none;\r\nborder-radius:999px;\r\nfont-size:14px;\r\nfont-weight:600;\r\nflex-shrink:0;\r\n}\r\n\r\n.avf-follow:hover{\r\nbackground:#1877F2;\r\n}\r\n\r\n/* Positions */\r\n\r\n.avf-p1{\r\ntop:8%;\r\nleft:5%;\r\n}\r\n\r\n.avf-p2{\r\ntop:8%;\r\nright:5%;\r\n}\r\n\r\n.avf-p3{\r\nbottom:8%;\r\nleft:5%;\r\n}\r\n\r\n.avf-p4{\r\nbottom:8%;\r\nright:5%;\r\n}\r\n\r\n.avf-p5{\r\ntop:50%;\r\nright:3%;\r\ntransform:translateY(-50%);\r\n}\r\n\r\n/* Mobile */\r\n\r\n@media(max-width:1200px){\r\n\r\nbody{\r\noverflow:auto;\r\npadding:40px 20px;\r\n}\r\n\r\n.avf-hero{\r\nposition:relative;\r\ntop:auto;\r\nleft:auto;\r\ntransform:none;\r\nmargin:0 auto 40px;\r\n}\r\n\r\n.avf-profile{\r\nposition:relative;\r\nwidth:100%;\r\nmax-width:420px;\r\nmargin:20px auto;\r\n}\r\n\r\n.avf-p1,.avf-p2,.avf-p3,.avf-p4,.avf-p5{\r\ntop:auto;\r\nright:auto;\r\nleft:auto;\r\nbottom:auto;\r\ntransform:none;\r\n}\r\n\r\n.avf-hero h1{\r\nfont-size:42px;\r\n}\r\n\r\n}\r\n\r\n</style>\r\n<div class=\"outer-layer\">\r\n<div class=\"avf-hero\">\r\n<h1>Follow Our Instagram</h1>\r\n\r\n<p>\r\nStay connected with our official Instagram pages for visa updates,\r\nsuccess stories, travel tips and exclusive content.\r\n</p>\r\n</div>\r\n\r\n<div class=\"avf-profile avf-p1\">\r\n<img src=\"https://ik.imagekit.io/kaveeshkapoor/website%20images/visaexpertsnoida.jpg\">\r\n<div class=\"avf-info\">\r\n<h3>Visa Experts Noida</h3>\r\n<span>@visaexpertsnoida</span>\r\n</div>\r\n<a class=\"avf-follow\" target=\"_blank\" href=\"https://www.instagram.com/visaexpertsnoida/\">Follow</a>\r\n</div>\r\n\r\n<div class=\"avf-profile avf-p2\">\r\n<img src=\"https://ik.imagekit.io/kaveeshkapoor/website%20images/avisa.experts.jpg\">\r\n<div class=\"avf-info\">\r\n<h3>A Visa Expert</h3>\r\n<span>@avisa.expert</span>\r\n</div>\r\n<a class=\"avf-follow\" target=\"_blank\" href=\"https://www.instagram.com/avisa.expert/\">Follow</a>\r\n</div>\r\n\r\n<div class=\"avf-profile avf-p3\">\r\n<img src=\"https://ik.imagekit.io/kaveeshkapoor/website%20images/yourimmigration.jpg\">\r\n<div class=\"avf-info\">\r\n<h3>Your Immigrations</h3>\r\n<span>@yourimmigrations</span>\r\n</div>\r\n<a class=\"avf-follow\" target=\"_blank\" href=\"https://www.instagram.com/yourimmigrations/\">Follow</a>\r\n</div>\r\n\r\n<div class=\"avf-profile avf-p4\">\r\n<img src=\"https://ik.imagekit.io/kaveeshkapoor/website%20images/teamvisaexperts.jpg\">\r\n<div class=\"avf-info\">\r\n<h3>Team Visa Experts</h3>\r\n<span>@teamvisaexperts</span>\r\n</div>\r\n<a class=\"avf-follow\" target=\"_blank