(86, '<link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\r\n\r\n<style>\r\n\r\n.outer-layer, .outer-layer * {\r\n  margin: 0;\r\n  padding: 0;\r\n  box-sizing: border-box;\r\n  font-family: \'Inter\', sans-serif;\r\n}\r\n\r\n.outer-layer {\r\n  background: #f8fafc;\r\n  padding: 40px 20px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  gap: 30px;\r\n  width: 100%;\r\n  max-width: 1200px;\r\n  margin: 0 auto;\r\n}\r\n\r\n/* Hero */\r\n\r\n.avf-hero {\r\n  text-align: center;\r\n  max-width: 650px;\r\n  width: 100%;\r\n}\r\n\r\n.avf-hero h1 {\r\n  font-size: 36px;\r\n  font-weight: 700;\r\n  color: #111827;\r\n  margin-bottom: 14px;\r\n}\r\n\r\n.avf-hero p {\r\n  font-size: 16px;\r\n  color: #6b7280;\r\n  line-height: 26px;\r\n}\r\n\r\n/* Profiles Grid */\r\n\r\n.avf-profiles-grid {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  justify-content: center;\r\n  gap: 20px;\r\n  width: 100%;\r\n}\r\n\r\n.avf-profile {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 14px;\r\n  width: 320px;\r\n  max-width: 100%;\r\n  padding: 12px 16px;\r\n  background: #fff;\r\n  border-radius: 60px;\r\n  border: 1px solid #e5e7eb;\r\n  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.04);\r\n  transition: transform 0.2s, box-shadow 0.2s;\r\n}\r\n\r\n.avf-profile:hover {\r\n  transform: translateY(-2px);\r\n  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.08);\r\n}\r\n\r\n.avf-profile img {\r\n  width: 58px;\r\n  height: 58px;\r\n  border-radius: 50%;\r\n  object-fit: cover;\r\n  border: 2px solid #E1306C;\r\n}\r\n\r\n.avf-info {\r\n  flex: 1;\r\n  min-width: 0;\r\n}\r\n\r\n.avf-info h3 {\r\n  font-size: 15px;\r\n  font-weight: 600;\r\n  color: #111827;\r\n  white-space: nowrap;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n}\r\n\r\n.avf-info span {\r\n  font-size: 13px;\r\n  color: #6b7280;\r\n  white-space: nowrap;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  display: block;\r\n